    "rpc_functions": [
        {
            "definition": "CREATE OR REPLACE FUNCTION public.auto_close_expired_class_sessions()\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\r\nDECLARE\r\n  v_active boolean;\r\n  v_raw_val text;\r\n  v_delay_hours numeric := 24;\r\n  v_closed_count integer := 0;\r\nBEGIN\r\n  SELECT is_active, config_value\r\n    INTO v_active, v_raw_val\r\n  FROM public.app_config\r\n  WHERE config_key = 'class_auto_close_hours'\r\n  LIMIT 1;\r\n\r\n  IF v_active IS FALSE THEN\r\n    RETURN 0;\r\n  END IF;\r\n\r\n  IF v_raw_val ~ '^[0-9]+(\\.[0-9]+)?$' THEN\r\n    v_delay_hours := GREATEST(0, v_raw_val::numeric);\r\n  END IF;\r\n\r\n  UPDATE public.class_sessions cs\r\n  SET\r\n    is_closed = true,\r\n    closed_at = now(),\r\n    closed_by = 'automatica',\r\n    closed_by_user_id = NULL\r\n  WHERE COALESCE(cs.is_closed, false) = false\r\n    AND ((cs.date::date + time '23:59:59') AT TIME ZONE 'Europe/Madrid')\r\n        + make_interval(hours => floor(v_delay_hours)::int, mins => round((v_delay_hours - floor(v_delay_hours)) * 60)::int) <= now()\r\n    AND (\r\n      cs.reopened_at IS NULL\r\n      OR cs.reopened_at + GREATEST(\r\n           make_interval(hours => floor(v_delay_hours)::int, mins => round((v_delay_hours - floor(v_delay_hours)) * 60)::int),\r\n           interval '1 hour'\r\n         ) <= now()\r\n    );\r\n\r\n  GET DIAGNOSTICS v_closed_count = ROW_COUNT;\r\n  RETURN v_closed_count;\r\nEND;\r\n$function$\n",
            "return_type": "integer",
            "function_name": "auto_close_expired_class_sessions",
            "identity_args": "",
            "config_settings": null,
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.can_access_status_history(p_entity_type text, p_entity_id text)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_uid_text text := auth.uid()::text;\r\n  v_entity text := NULLIF(trim(COALESCE(p_entity_id, '')), '');\r\nBEGIN\r\n  IF v_uid_text IS NULL OR v_entity IS NULL THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  IF p_entity_type = 'profile' THEN\r\n    RETURN v_entity = v_uid_text;\r\n  ELSIF p_entity_type = 'student' THEN\r\n    RETURN public.is_own_student(v_entity) OR public.teacher_teaches_student(v_entity);\r\n  ELSIF p_entity_type = 'teacher' THEN\r\n    RETURN public.is_own_teacher(v_entity);\r\n  END IF;\r\n\r\n  RETURN false;\r\nEND;\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "can_access_status_history",
            "identity_args": "p_entity_type text, p_entity_id text",
            "config_settings": [
                "search_path=public, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.can_access_withdrawal_request(p_user_id text, p_profile_id text, p_student_id text, p_teacher_id text)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_uid_text text := auth.uid()::text;\r\nBEGIN\r\n  IF v_uid_text IS NULL THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  RETURN NULLIF(trim(COALESCE(p_user_id, '')), '') = v_uid_text\r\n      OR NULLIF(trim(COALESCE(p_profile_id, '')), '') = v_uid_text\r\n      OR public.is_own_student(p_student_id)\r\n      OR public.is_own_teacher(p_teacher_id);\r\nEND;\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "can_access_withdrawal_request",
            "identity_args": "p_user_id text, p_profile_id text, p_student_id text, p_teacher_id text",
            "config_settings": [
                "search_path=public, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.cancel_activity_unenrollment_request(p_activity_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_student_id uuid;\r\n  v_updated int := 0;\r\nBEGIN\r\n  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Sesión no autorizada.');\r\n  END IF;\r\n\r\n  v_student_id := public.current_student_id();\r\n  IF v_student_id IS NULL THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'No tienes ficha de alumno vinculada.');\r\n  END IF;\r\n\r\n  UPDATE public.student_enrollments\r\n  SET status = 'active',\r\n      drop_requested_at = NULL,\r\n      drop_reason = NULL\r\n  WHERE student_id = v_student_id\r\n    AND activity_id = p_activity_id\r\n    AND active IS DISTINCT FROM false\r\n    AND status IN ('pending_unenroll', 'pending_withdrawal');\r\n\r\n  GET DIAGNOSTICS v_updated = ROW_COUNT;\r\n  IF v_updated = 0 THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'No existe solicitud de baja pendiente.');\r\n  END IF;\r\n\r\n  RETURN jsonb_build_object('success', true);\r\nEND;\r\n$function$\n",
            "return_type": "jsonb",
            "function_name": "cancel_activity_unenrollment_request",
            "identity_args": "p_activity_id uuid",
            "config_settings": [
                "search_path=public, auth, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.confirm_association_withdrawal(p_request_id uuid, p_debts_checked boolean DEFAULT true, p_materials_checked boolean DEFAULT true, p_notes text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_req public.membership_withdrawal_requests%ROWTYPE;\r\nBEGIN\r\n  IF auth.uid() IS NULL OR NOT public.is_admin() THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Solo administración puede confirmar bajas de asociación.');\r\n  END IF;\r\n\r\n  IF NOT (coalesce(p_debts_checked, false) AND coalesce(p_materials_checked, false)) THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Debes confirmar deudas y devolución de materiales.');\r\n  END IF;\r\n\r\n  SELECT * INTO v_req\r\n  FROM public.membership_withdrawal_requests\r\n  WHERE id = p_request_id AND status = 'pending'\r\n  FOR UPDATE;\r\n\r\n  IF NOT FOUND THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Solicitud no encontrada o ya resuelta.');\r\n  END IF;\r\n\r\n  UPDATE public.membership_withdrawal_requests\r\n  SET status = 'approved',\r\n      debts_checked = true,\r\n      materials_checked = true,\r\n      resolution_notes = nullif(trim(coalesce(p_notes, '')), ''),\r\n      resolved_by = auth.uid(),\r\n      resolved_at = now(),\r\n      updated_at = now()\r\n  WHERE id = p_request_id;\r\n\r\n  IF v_req.profile_id IS NOT NULL THEN\r\n    PERFORM set_config('app.bypass_profile_guard', 'on', true);\r\n    UPDATE public.profiles\r\n    SET access = false,\r\n        active = false,\r\n        end_date = CURRENT_DATE,\r\n        access_status = 'rejected',\r\n        approval_status = 'rejected'\r\n    WHERE id = v_req.profile_id\r\n      AND lower(trim(email)) <> 'cristino.conde@actriskell.org';\r\n  END IF;\r\n\r\n  IF v_req.student_id IS NOT NULL THEN\r\n    UPDATE public.students\r\n    SET status = 'inactive',\r\n        end_date = CURRENT_DATE\r\n    WHERE id = v_req.student_id;\r\n\r\n    UPDATE public.student_enrollments\r\n    SET active = false,\r\n        status = 'inactive',\r\n        deleted_at = now(),\r\n        ended_at = CURRENT_DATE\r\n    WHERE student_id = v_req.student_id\r\n      AND active IS DISTINCT FROM false;\r\n  END IF;\r\n\r\n  IF v_req.teacher_id IS NOT NULL THEN\r\n    UPDATE public.teachers\r\n    SET active = false,\r\n        end_date = CURRENT_DATE\r\n    WHERE id = v_req.teacher_id;\r\n  END IF;\r\n\r\n  RETURN jsonb_build_object('success', true);\r\nEND;\r\n$function$\n",
            "return_type": "jsonb",
            "function_name": "confirm_association_withdrawal",
            "identity_args": "p_request_id uuid, p_debts_checked boolean, p_materials_checked boolean, p_notes text",
            "config_settings": [
                "search_path=public, auth, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.current_student_id()\n RETURNS uuid\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\n  SELECT coalesce(\r\n    (\r\n      SELECT p.student_id\r\n      FROM public.profiles p\r\n      WHERE p.id = auth.uid()\r\n        AND p.access = true\r\n        AND p.active = true\r\n      LIMIT 1\r\n    ),\r\n    (\r\n      SELECT s.id\r\n      FROM public.students s\r\n      JOIN public.profiles p ON p.id = auth.uid()\r\n      WHERE p.access = true\r\n        AND p.active = true\r\n        AND (\r\n          s.profile_id = p.id\r\n          OR lower(trim(s.email)) = lower(trim(p.email))\r\n        )\r\n      LIMIT 1\r\n    )\r\n  );\r\n$function$\n",
            "return_type": "uuid",
            "function_name": "current_student_id",
