        {
            "definition": "CREATE OR REPLACE FUNCTION public.current_student_id_text()\n RETURNS text\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_uid uuid := auth.uid();\r\n  v_prof public.profiles%ROWTYPE;\r\n  v_student_id text;\r\n  v_email text;\r\nBEGIN\r\n  IF v_uid IS NULL THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  SELECT * INTO v_prof\r\n  FROM public.profiles\r\n  WHERE id = v_uid\r\n  LIMIT 1;\r\n\r\n  IF FOUND AND v_prof.student_id IS NOT NULL THEN\r\n    RETURN v_prof.student_id::text;\r\n  END IF;\r\n\r\n  v_email := lower(trim(COALESCE(v_prof.email, '')));\r\n\r\n  SELECT s.id::text INTO v_student_id\r\n  FROM public.students s\r\n  WHERE (\r\n      NULLIF(to_jsonb(s)->>'profile_id', '') = v_uid::text\r\n      OR (v_email <> '' AND lower(trim(COALESCE(s.email, ''))) = v_email)\r\n    )\r\n  ORDER BY (COALESCE(s.status::text, 'active') = 'active') DESC,\r\n           COALESCE(to_jsonb(s)->>'created_at', '') DESC\r\n  LIMIT 1;\r\n\r\n  RETURN v_student_id;\r\nEND;\r\n$function$\n",
            "return_type": "text",
            "function_name": "current_student_id_text",
            "identity_args": "",
            "config_settings": [
