            "definition": "CREATE OR REPLACE FUNCTION public.current_teacher_id()\n RETURNS uuid\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\n  SELECT coalesce(\r\n    (\r\n      SELECT p.teacher_id\r\n      FROM public.profiles p\r\n      WHERE p.id = auth.uid()\r\n        AND p.access = true\r\n        AND p.active = true\r\n      LIMIT 1\r\n    ),\r\n    (\r\n      SELECT t.id\r\n      FROM public.teachers t\r\n      JOIN public.profiles p ON p.id = auth.uid()\r\n      WHERE p.access = true\r\n        AND p.active = true\r\n        AND lower(trim(t.email)) = lower(trim(p.email))\r\n      LIMIT 1\r\n    )\r\n  );\r\n$function$\n",
