        {
            "definition": "CREATE OR REPLACE FUNCTION public.current_teacher_id_text()\n RETURNS text\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_uid uuid := auth.uid();\r\n  v_prof public.profiles%ROWTYPE;\r\n  v_teacher_id text;\r\n  v_email text;\r\nBEGIN\r\n  IF v_uid IS NULL THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  SELECT * INTO v_prof\r\n  FROM public.profiles\r\n  WHERE id = v_uid\r\n  LIMIT 1;\r\n\r\n  IF FOUND AND v_prof.teacher_id IS NOT NULL THEN\r\n    RETURN v_prof.teacher_id::text;\r\n  END IF;\r\n\r\n  v_email := lower(trim(COALESCE(v_prof.email, '')));\r\n\r\n  SELECT tc.id::text INTO v_teacher_id\r\n  FROM public.teachers tc\r\n  WHERE (\r\n      NULLIF(to_jsonb(tc)->>'profile_id', '') = v_uid::text\r\n      OR (v_email <> '' AND lower(trim(COALESCE(tc.email, ''))) = v_email)\r\n    )\r\n    AND COALESCE(tc.active, true) = true\r\n  ORDER BY COALESCE(to_jsonb(tc)->>'created_at', '') DESC\r\n  LIMIT 1;\r\n\r\n  RETURN v_teacher_id;\r\nEND;\r\n$function$\n",
            "return_type": "text",
            "function_name": "current_teacher_id_text",
            "identity_args": "",
            "config_settings": [
                "search_path=public, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.current_user_has_effective_access()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.profiles p\r\n    WHERE (\r\n      p.id = auth.uid()\r\n      OR lower(trim(coalesce(p.email, ''))) = lower(trim(coalesce(auth.jwt() ->> 'email', '')))\r\n    )\r\n    AND (\r\n      lower(trim(coalesce(p.email, ''))) = 'cristino.conde@actriskell.org'\r\n      OR (\r\n        coalesce(p.access, p.active, false) = true\r\n        AND coalesce(p.approval_status, 'pending') = 'approved'\r\n        AND p.role IN ('admin', 'teacher', 'student', 'hybrid', 'member')\r\n        AND (p.end_date IS NULL OR p.end_date > current_date)\r\n      )\r\n    )\r\n  );\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "current_user_has_effective_access",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.current_user_has_role(allowed_roles text[])\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.profiles p\r\n    WHERE (\r\n      p.id = auth.uid()\r\n      OR (\r\n        COALESCE(auth.jwt() ->> 'email', '') <> ''\r\n        AND lower(trim(COALESCE(p.email, ''))) = lower(trim(auth.jwt() ->> 'email'))\r\n      )\r\n    )\r\n    AND COALESCE(p.access, p.active, false) = true\r\n    AND (p.end_date IS NULL OR p.end_date > CURRENT_DATE)\r\n    AND p.role = ANY(allowed_roles)\r\n  );\r\n$function$\n",
            "return_type": "boolean",
