        {
            "definition": "CREATE OR REPLACE FUNCTION public.derive_user_operational_role(p_student_id uuid, p_teacher_id uuid, p_email text, p_profile_id uuid)\n RETURNS operational_role_type\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_email_norm text := lower(trim(coalesce(p_email, '')));\r\n  v_has_student boolean := false;\r\n  v_has_teacher boolean := false;\r\nBEGIN\r\n  -- Solo cuentan alumnos aprobados/activos con matrícula confirmada en taller activo (ignora 'pending')\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.students s\r\n    JOIN public.student_enrollments se ON se.student_id = s.id\r\n    JOIN public.activities a ON a.id = se.activity_id\r\n    WHERE (\r\n      (p_student_id IS NOT NULL AND s.id = p_student_id)\r\n      OR (p_profile_id IS NOT NULL AND s.profile_id = p_profile_id)\r\n      OR (v_email_norm <> '' AND lower(trim(coalesce(s.email, ''))) = v_email_norm)\r\n    )\r\n      AND coalesce(s.status, 'active') NOT IN ('inactive', 'pending', 'pending_validation')\r\n      AND coalesce(s.validation_status, 'validated') <> 'pending'\r\n      AND coalesce(se.active, true) = true\r\n      AND coalesce(se.status, 'active') NOT IN ('pending', 'pending_validation', 'inactive', 'rejected')\r\n      AND se.deleted_at IS NULL\r\n      AND coalesce(a.active, true) = true\r\n      AND coalesce(a.status, 'active') NOT IN ('pending', 'pending_validation', 'inactive')\r\n  ) INTO v_has_student;\r\n\r\n  -- Solo cuentan monitores aprobados/activos con al menos un taller activo aprobado (ignora 'pending')\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.teachers t\r\n    JOIN public.activities a ON a.teacher_id = t.id\r\n    WHERE (\r\n      (p_teacher_id IS NOT NULL AND t.id = p_teacher_id)\r\n      OR (v_email_norm <> '' AND lower(trim(coalesce(t.email, ''))) = v_email_norm)\r\n    )\r\n      AND coalesce(t.active, true) = true\r\n      AND coalesce(t.status, 'active') NOT IN ('pending', 'pending_validation', 'inactive')\r\n      AND coalesce(a.active, true) = true\r\n      AND coalesce(a.status, 'active') NOT IN ('pending', 'pending_validation', 'inactive')\r\n  ) INTO v_has_teacher;\r\n\r\n  IF v_has_student AND v_has_teacher THEN\r\n    RETURN 'hibrido';\r\n  ELSIF v_has_student THEN\r\n    RETURN 'alumno';\r\n  ELSIF v_has_teacher THEN\r\n    RETURN 'profesor';\r\n  ELSE\r\n    RETURN 'vacio';\r\n  END IF;\r\nEND;\r\n$function$\n",
            "return_type": "operational_role_type",
            "function_name": "derive_user_operational_role",
            "identity_args": "p_student_id uuid, p_teacher_id uuid, p_email text, p_profile_id uuid",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.enforce_class_session_closure_rules()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\r\nBEGIN\r\n  IF TG_OP = 'DELETE' THEN\r\n    IF COALESCE(OLD.is_closed, false) = true THEN\r\n      RAISE EXCEPTION 'No se puede eliminar una clase cerrada; debe reabrirse primero indicando un motivo.';\r\n    END IF;\r\n    RETURN OLD;\r\n  END IF;\r\n\r\n  IF TG_OP = 'UPDATE' THEN\r\n    -- Si estaba cerrada y pasa a abierta, exigir motivo de reapertura\r\n    IF COALESCE(OLD.is_closed, false) = true AND COALESCE(NEW.is_closed, false) = false THEN\r\n      IF NULLIF(btrim(COALESCE(NEW.reopen_reason, '')), '') IS NULL THEN\r\n        RAISE EXCEPTION 'Es obligatorio indicar un motivo o explicación para reabrir una clase cerrada.';\r\n      END IF;\r\n      NEW.closed_at := NULL;\r\n      NEW.closed_by := NULL;\r\n      NEW.closed_by_user_id := NULL;\r\n      NEW.reopened_at := COALESCE(NEW.reopened_at, now());\r\n      RETURN NEW;\r\n    END IF;\r\n\r\n    -- Si permanece cerrada, bloquear cambios de contenido/datos de la clase\r\n    IF COALESCE(OLD.is_closed, false) = true AND COALESCE(NEW.is_closed, false) = true THEN\r\n      IF NEW.activity_id IS DISTINCT FROM OLD.activity_id\r\n         OR NEW.teacher_id IS DISTINCT FROM OLD.teacher_id\r\n         OR NEW.date IS DISTINCT FROM OLD.date\r\n         OR NEW.duration_minutes IS DISTINCT FROM OLD.duration_minutes\r\n         OR COALESCE(NEW.topic, '') IS DISTINCT FROM COALESCE(OLD.topic, '') THEN\r\n        RAISE EXCEPTION 'La clase está cerrada (solo lectura). Reábrela indicando un motivo para poder editarla.';\r\n      END IF;\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "enforce_class_session_closure_rules",
            "identity_args": "",
            "config_settings": null,
            "anon_can_execute": true,
            "is_security_definer": false,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.format_socio_member_number(raw_val text)\n RETURNS text\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\r\nDECLARE\r\n  v_trimmed TEXT;\r\n  v_digits  TEXT;\r\nBEGIN\r\n  IF raw_val IS NULL OR btrim(raw_val) = '' THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  v_trimmed := btrim(raw_val);\r\n  v_digits  := regexp_replace(v_trimmed, '\\D', '', 'g');\r\n\r\n  IF length(v_digits) > 0 THEN\r\n    RETURN lpad(v_digits, 5, '0');\r\n  END IF;\r\n\r\n  RETURN lpad(v_trimmed, 5, '0');\r\nEND;\r\n$function$\n",
            "return_type": "text",
            "function_name": "format_socio_member_number",
            "identity_args": "raw_val text",
            "config_settings": null,
            "anon_can_execute": true,
            "is_security_definer": false,
            "authenticated_can_execute": true
        },
