        {
            "definition": "CREATE OR REPLACE FUNCTION public.guard_profile_role()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\nBEGIN\r\n  IF NEW.role IS DISTINCT FROM OLD.role AND auth.uid() IS NOT NULL AND NOT private.is_admin() THEN\r\n    RAISE EXCEPTION 'Solo un administrador puede cambiar el rol de un usuario' USING ERRCODE = '42501';\r\n  END IF;\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "guard_profile_role",
            "identity_args": "",
            "config_settings": [
                "search_path=\"\""
            ],
            "anon_can_execute": false,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.guard_profiles_role_and_links()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  is_service boolean;\r\nBEGIN\r\n  is_service := current_user IN ('postgres', 'supabase_admin', 'service_role')\r\n    OR COALESCE(current_setting('request.jwt.claim.role', true), '') = 'service_role'\r\n    OR COALESCE(current_setting('app.allow_profile_role_sync', true), '') = 'on';\r\n\r\n  IF is_service OR public.is_admin() THEN\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  IF NEW.role IS DISTINCT FROM OLD.role\r\n     OR NEW.access IS DISTINCT FROM OLD.access\r\n     OR NEW.active IS DISTINCT FROM OLD.active\r\n     OR NEW.access_status IS DISTINCT FROM OLD.access_status\r\n     OR NEW.approval_status IS DISTINCT FROM OLD.approval_status\r\n     OR NEW.is_socio IS DISTINCT FROM OLD.is_socio\r\n     OR NEW.operational_role IS DISTINCT FROM OLD.operational_role\r\n     OR NEW.teacher_id IS DISTINCT FROM OLD.teacher_id\r\n     OR NEW.student_id IS DISTINCT FROM OLD.student_id THEN\r\n    RAISE EXCEPTION 'Solo la administración puede modificar el rol, estado de acceso o vínculos de perfil.';\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "guard_profiles_role_and_links",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.guard_profiles_soft_delete()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  is_service boolean;\r\nBEGIN\r\n  IF TG_OP = 'DELETE' THEN\r\n    RAISE EXCEPTION 'No se permite eliminar perfiles directamente; utiliza baja lógica (active = false).';\r\n  END IF;\r\n\r\n  is_service := current_user IN ('postgres', 'supabase_admin', 'service_role')\r\n    OR COALESCE(current_setting('request.jwt.claim.role', true), '') = 'service_role'\r\n    OR COALESCE(current_setting('app.allow_profile_role_sync', true), '') = 'on';\r\n\r\n  IF TG_OP = 'UPDATE' THEN\r\n    IF lower(trim(COALESCE(OLD.email, ''))) = 'cristino.conde@actriskell.org'\r\n       AND (NEW.active IS FALSE OR NEW.access IS FALSE) THEN\r\n      RAISE EXCEPTION 'No se puede dar de baja al administrador principal.';\r\n    END IF;\r\n\r\n    IF NOT is_service AND NOT public.is_admin() THEN\r\n      IF NEW.active IS DISTINCT FROM OLD.active\r\n         OR NEW.access IS DISTINCT FROM OLD.access\r\n         OR NEW.access_status IS DISTINCT FROM OLD.access_status\r\n         OR NEW.approval_status IS DISTINCT FROM OLD.approval_status\r\n         OR NEW.role IS DISTINCT FROM OLD.role\r\n         OR NEW.teacher_id IS DISTINCT FROM OLD.teacher_id\r\n         OR NEW.student_id IS DISTINCT FROM OLD.student_id\r\n         OR NEW.end_date IS DISTINCT FROM OLD.end_date THEN\r\n        RAISE EXCEPTION 'Solo la administración puede modificar el estado de acceso, rol o vínculos.';\r\n      END IF;\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "guard_profiles_soft_delete",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.handle_auth_user_after_insert()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_email text := lower(trim(coalesce(NEW.email, '')));\r\n  v_name text := coalesce(\r\n    nullif(trim(NEW.raw_user_meta_data->>'full_name'), ''),\r\n    nullif(trim(NEW.raw_user_meta_data->>'name'), ''),\r\n    split_part(v_email, '@', 1),\r\n    'Usuario'\r\n  );\r\n  v_avatar text := nullif(trim(coalesce(NEW.raw_user_meta_data->>'avatar_url', NEW.raw_user_meta_data->>'picture', '')), '');\r\n  v_existing_id uuid;\r\nBEGIN\r\n  IF v_email = 'cristino.conde@actriskell.org' THEN\r\n    INSERT INTO public.profiles (\r\n      id, email, full_name, avatar_url, role, operational_role,\r\n      is_socio, access, active, access_status, approval_status, end_date\r\n    ) VALUES (\r\n      NEW.id, v_email, v_name, v_avatar, 'Admin', 'vacio',\r\n      true, true, true, 'approved', 'approved', NULL\r\n    )\r\n    ON CONFLICT (id) DO UPDATE SET\r\n      email = EXCLUDED.email,\r\n      role = 'Admin',\r\n      access = true,\r\n      active = true,\r\n      access_status = 'approved',\r\n      approval_status = 'approved',\r\n      end_date = NULL;\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  SELECT p.id INTO v_existing_id\r\n  FROM public.profiles p\r\n  WHERE lower(trim(p.email)) = v_email\r\n  LIMIT 1;\r\n\r\n  IF v_existing_id IS NOT NULL AND v_existing_id <> NEW.id THEN\r\n    UPDATE public.profiles\r\n    SET id = NEW.id,\r\n        full_name = coalesce(nullif(trim(full_name), ''), v_name),\r\n        avatar_url = coalesce(avatar_url, v_avatar)\r\n    WHERE id = v_existing_id;\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  IF v_existing_id IS NULL THEN\r\n    INSERT INTO public.profiles (\r\n      id, email, full_name, avatar_url, role, operational_role,\r\n      is_socio, access, active, access_status, approval_status, start_date, end_date\r\n    ) VALUES (\r\n      NEW.id, v_email, v_name, v_avatar, 'Socio', 'vacio',\r\n      false, false, false, 'pending', 'pending', CURRENT_DATE, NULL\r\n    )\r\n    ON CONFLICT (id) DO NOTHING;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "handle_auth_user_after_insert",
            "identity_args": "",
            "config_settings": [
                "search_path=public, auth, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.handle_auth_user_whitelist_before_insert()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_email text := lower(trim(coalesce(NEW.email, '')));\r\n  v_provider text := lower(trim(coalesce(NEW.raw_app_meta_data->>'provider', '')));\r\n  v_is_google boolean := (\r\n    v_provider = 'google'\r\n    OR coalesce(NEW.raw_app_meta_data->'providers', '[]'::jsonb) ? 'google'\r\n  );\r\n  v_is_preauthorized boolean := false;\r\nBEGIN\r\n  IF v_email = '' THEN\r\n    RAISE EXCEPTION 'Correo electrónico obligatorio.' USING ERRCODE = '42501';\r\n  END IF;\r\n\r\n  IF NEW.raw_user_meta_data IS NOT NULL THEN\r\n    NEW.raw_user_meta_data := NEW.raw_user_meta_data\r\n      - 'role'\r\n      - 'operational_role'\r\n      - 'access'\r\n      - 'active'\r\n      - 'access_status'\r\n      - 'approval_status'\r\n      - 'is_socio'\r\n      - 'member_type';\r\n  END IF;\r\n\r\n  IF v_email = 'cristino.conde@actriskell.org' THEN\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.profiles p\r\n    WHERE lower(trim(p.email)) = v_email\r\n      AND coalesce(p.access_status, 'approved') <> 'rejected'\r\n  ) INTO v_is_preauthorized;\r\n\r\n  IF NOT v_is_preauthorized AND NOT v_is_google THEN\r\n    RAISE EXCEPTION 'Registro no autorizado. Solicita acceso a la administración.' USING ERRCODE = '42501';\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "handle_auth_user_whitelist_before_insert",
            "identity_args": "",
            "config_settings": [
                "search_path=public, auth, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.handle_new_auth_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  assigned_role TEXT := 'member';\r\n  linked_teacher_id UUID := NULL;\r\n  linked_student_id UUID := NULL;\r\n  user_full_name TEXT;\r\n  normalized_email TEXT := lower(trim(COALESCE(NEW.email, '')));\r\n  requested_role TEXT := lower(trim(COALESCE(NEW.raw_user_meta_data ->> 'role', '')));\r\n  initial_access BOOLEAN := false;\r\nBEGIN\r\n  SELECT id INTO linked_teacher_id\r\n  FROM public.teachers\r\n  WHERE lower(trim(email)) = normalized_email\r\n  LIMIT 1;\r\n\r\n  SELECT id INTO linked_student_id\r\n  FROM public.students\r\n  WHERE lower(trim(email)) = normalized_email\r\n  LIMIT 1;\r\n\r\n  IF normalized_email = 'cristino.conde@actriskell.org' THEN\r\n    assigned_role := 'admin';\r\n    initial_access := true;\r\n  ELSIF requested_role IN ('admin', 'teacher', 'student', 'hybrid', 'member') THEN\r\n    assigned_role := requested_role;\r\n  ELSIF requested_role = 'teacher_student' THEN\r\n    assigned_role := 'hybrid';\r\n  ELSIF requested_role = 'socio' THEN\r\n    assigned_role := 'member';\r\n  ELSIF linked_teacher_id IS NOT NULL AND linked_student_id IS NOT NULL THEN\r\n    assigned_role := 'hybrid';\r\n  ELSIF linked_teacher_id IS NOT NULL THEN\r\n    assigned_role := 'teacher';\r\n  ELSIF linked_student_id IS NOT NULL THEN\r\n    assigned_role := 'student';\r\n  ELSE\r\n    assigned_role := 'member';\r\n  END IF;\r\n\r\n  user_full_name := COALESCE(\r\n    NULLIF(trim(NEW.raw_user_meta_data ->> 'full_name'), ''),\r\n    NULLIF(trim(NEW.raw_user_meta_data ->> 'name'), ''),\r\n    split_part(normalized_email, '@', 1)\r\n  );\r\n\r\n  INSERT INTO public.profiles (\r\n    id, email, full_name, avatar_url, role, access, active, teacher_id, student_id\r\n  ) VALUES (\r\n    NEW.id,\r\n    normalized_email,\r\n    user_full_name,\r\n    COALESCE(NEW.raw_user_meta_data ->> 'avatar_url', NEW.raw_user_meta_data ->> 'picture'),\r\n    assigned_role,\r\n    initial_access,\r\n    initial_access,\r\n    linked_teacher_id,\r\n    linked_student_id\r\n  )\r\n  ON CONFLICT (id) DO UPDATE SET\r\n    email = EXCLUDED.email,\r\n    full_name = EXCLUDED.full_name,\r\n    avatar_url = COALESCE(EXCLUDED.avatar_url, public.profiles.avatar_url),\r\n    access = COALESCE(public.profiles.access, public.profiles.active, EXCLUDED.access),\r\n    active = COALESCE(public.profiles.active, public.profiles.access, EXCLUDED.active),\r\n    teacher_id = COALESCE(EXCLUDED.teacher_id, public.profiles.teacher_id),\r\n    student_id = COALESCE(EXCLUDED.student_id, public.profiles.student_id);\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "handle_new_auth_user",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.handle_new_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_email text;\r\n  v_full_name text;\r\n  v_avatar_url text;\r\n  v_is_master boolean;\r\n  v_raw_role text;\r\n  v_role text;\r\n  v_access boolean;\r\n  v_is_socio boolean;\r\n  v_status text;\r\nBEGIN\r\n  v_email := lower(trim(COALESCE(NEW.email, '')));\r\n  v_is_master := (v_email = 'cristino.conde@actriskell.org');\r\n\r\n  v_full_name := COALESCE(\r\n    NULLIF(trim(NEW.raw_user_meta_data ->> 'full_name'), ''),\r\n    NULLIF(trim(NEW.raw_user_meta_data ->> 'name'), ''),\r\n    NULLIF(trim(concat_ws(' ', NEW.raw_user_meta_data ->> 'given_name', NEW.raw_user_meta_data ->> 'family_name')), ''),\r\n    NULLIF(trim(concat_ws(' ', NEW.raw_user_meta_data ->> 'first_name', NEW.raw_user_meta_data ->> 'last_name')), ''),\r\n    NULLIF(split_part(v_email, '@', 1), ''),\r\n    'Usuario'\r\n  );\r\n\r\n  IF lower(trim(v_full_name)) IN ('aaa', 'usuario', 'user', 'sin nombre', 'no name', 'placeholder', 'test') THEN\r\n    v_full_name := COALESCE(NULLIF(split_part(v_email, '@', 1), ''), v_full_name);\r\n  END IF;\r\n\r\n  v_avatar_url := COALESCE(\r\n    NULLIF(trim(NEW.raw_user_meta_data ->> 'avatar_url'), ''),\r\n    NULLIF(trim(NEW.raw_user_meta_data ->> 'picture'), '')\r\n  );\r\n\r\n  IF v_is_master THEN\r\n    v_role := 'admin';\r\n    v_access := true;\r\n    v_is_socio := COALESCE((NEW.raw_user_meta_data ->> 'is_socio')::boolean, true);\r\n    v_status := 'approved';\r\n  ELSE\r\n    v_raw_role := lower(trim(COALESCE(NEW.raw_user_meta_data ->> 'role', '')));\r\n    v_role := CASE v_raw_role\r\n      WHEN 'admin' THEN 'admin'\r\n      WHEN 'administrador' THEN 'admin'\r\n      WHEN 'monitor' THEN 'teacher'\r\n      WHEN 'teacher' THEN 'teacher'\r\n      WHEN 'profesor' THEN 'teacher'\r\n      WHEN 'alumno' THEN 'student'\r\n      WHEN 'student' THEN 'student'\r\n      WHEN 'híbrido' THEN 'hybrid'\r\n      WHEN 'hibrido' THEN 'hybrid'\r\n      WHEN 'hybrid' THEN 'hybrid'\r\n      WHEN 'teacher_student' THEN 'hybrid'\r\n      ELSE 'member'\r\n    END;\r\n    v_access := COALESCE((NEW.raw_user_meta_data ->> 'access')::boolean, false);\r\n    v_is_socio := COALESCE((NEW.raw_user_meta_data ->> 'is_socio')::boolean, false);\r\n    v_status := CASE WHEN v_access THEN 'approved' ELSE 'pending' END;\r\n  END IF;\r\n\r\n  INSERT INTO public.profiles (\r\n    id,\r\n    email,\r\n    full_name,\r\n    avatar_url,\r\n    role,\r\n    access,\r\n    active,\r\n    access_status,\r\n    approval_status,\r\n    is_socio,\r\n    member_type,\r\n    start_date\r\n  )\r\n  VALUES (\r\n    NEW.id,\r\n    v_email,\r\n    v_full_name,\r\n    v_avatar_url,\r\n    v_role,\r\n    v_access,\r\n    v_access,\r\n    v_status,\r\n    v_status,\r\n    v_is_socio,\r\n    CASE\r\n      WHEN v_is_socio THEN 'socio'\r\n      WHEN v_role IN ('teacher', 'hybrid') THEN 'monitor_no_socio'\r\n      ELSE 'alumno_no_socio'\r\n    END,\r\n    CURRENT_DATE\r\n  )\r\n  ON CONFLICT (id) DO UPDATE SET\r\n    email = CASE\r\n      WHEN NULLIF(trim(EXCLUDED.email), '') IS NOT NULL THEN EXCLUDED.email\r\n      ELSE public.profiles.email\r\n    END,\r\n    full_name = CASE\r\n      WHEN lower(trim(COALESCE(public.profiles.full_name, ''))) IN ('', 'aaa', 'usuario', 'user', 'sin nombre', 'no name', 'placeholder', 'test')\r\n        THEN EXCLUDED.full_name\r\n      ELSE public.profiles.full_name\r\n    END,\r\n    avatar_url = COALESCE(NULLIF(trim(public.profiles.avatar_url), ''), EXCLUDED.avatar_url),\r\n    access_status = COALESCE(\r\n      NULLIF(trim(public.profiles.access_status), ''),\r\n      NULLIF(trim(public.profiles.approval_status), ''),\r\n      CASE WHEN COALESCE(public.profiles.access, false) THEN 'approved' ELSE 'pending' END\r\n    ),\r\n    approval_status = COALESCE(\r\n      NULLIF(trim(public.profiles.approval_status), ''),\r\n      NULLIF(trim(public.profiles.access_status), ''),\r\n      CASE WHEN COALESCE(public.profiles.access, false) THEN 'approved' ELSE 'pending' END\r\n    );\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "handle_new_user",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.handle_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\r\nBEGIN\r\n  NEW.updated_at = timezone('utc'::text, now());\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "handle_updated_at",
            "identity_args": "",
            "config_settings": null,
            "anon_can_execute": true,
            "is_security_definer": false,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.is_active_user()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.profiles p\r\n    WHERE p.id = auth.uid()\r\n      AND p.access = true\r\n      AND p.active = true\r\n      AND coalesce(p.access_status, 'approved') = 'approved'\r\n      AND (p.end_date IS NULL OR p.end_date::date > CURRENT_DATE)\r\n  );\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "is_active_user",
            "identity_args": "",
            "config_settings": [
                "search_path=public, auth, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.is_admin()\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_uid uuid := auth.uid();\r\n  v_prof public.profiles%ROWTYPE;\r\n  v_role text;\r\n  v_op_role text;\r\nBEGIN\r\n  IF v_uid IS NULL OR NOT public.is_approved_user() THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  SELECT * INTO v_prof\r\n  FROM public.profiles\r\n  WHERE id = v_uid\r\n  LIMIT 1;\r\n\r\n  IF NOT FOUND THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  v_role := lower(trim(COALESCE(v_prof.role::text, '')));\r\n  v_op_role := lower(trim(COALESCE(v_prof.operational_role::text, '')));\r\n\r\n  RETURN v_role IN ('admin', 'administrador')\r\n      OR v_op_role IN ('admin', 'administrador');\r\nEND;\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "is_admin",
            "identity_args": "",
            "config_settings": [
                "search_path=public, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.is_admin_or_teacher()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.profiles p\r\n    WHERE p.id = auth.uid()\r\n      AND COALESCE(p.access, p.active, false) = true\r\n      AND p.role IN ('admin', 'teacher', 'hybrid')\r\n  );\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "is_admin_or_teacher",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.is_admin_user()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\n  SELECT public.is_admin();\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "is_admin_user",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.is_approved_user()\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_uid uuid := auth.uid();\r\n  v_prof public.profiles%ROWTYPE;\r\n  v_json jsonb;\r\n  v_access_status text;\r\n  v_approval_status text;\r\nBEGIN\r\n  IF v_uid IS NULL THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  SELECT * INTO v_prof\r\n  FROM public.profiles\r\n  WHERE id = v_uid\r\n  LIMIT 1;\r\n\r\n  IF NOT FOUND THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  v_json := to_jsonb(v_prof);\r\n  v_access_status := lower(COALESCE(v_json->>'access_status', ''));\r\n  v_approval_status := lower(COALESCE(v_json->>'approval_status', ''));\r\n\r\n  IF COALESCE(v_prof.access, false) IS NOT true THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  IF v_prof.active IS false THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  IF v_prof.end_date IS NOT NULL THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  IF v_access_status IN ('pending', 'rejected', 'revoked', 'inactive')\r\n     OR v_approval_status IN ('pending', 'rejected', 'revoked', 'inactive') THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  RETURN true;\r\nEND;\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "is_approved_user",
            "identity_args": "",
            "config_settings": [
                "search_path=public, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.is_current_user_active()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\n  SELECT public.current_user_has_effective_access();\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "is_current_user_active",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
