            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.is_current_user_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\n  SELECT\r\n    lower(trim(coalesce(auth.jwt() ->> 'email', ''))) IN ('cristino.conde@actriskell.org')\r\n    OR EXISTS (\r\n      SELECT 1\r\n      FROM public.profiles p\r\n      WHERE (\r\n        p.id = auth.uid()\r\n        OR (\r\n          coalesce(auth.jwt() ->> 'email', '') <> ''\r\n          AND lower(trim(p.email)) = lower(trim(auth.jwt() ->> 'email'))\r\n        )\r\n      )\r\n      AND lower(trim(coalesce(p.role, ''))) IN ('admin', 'administrador', 'administrator')\r\n      AND coalesce(p.access, true) = true\r\n      AND coalesce(p.active, true) = true\r\n      AND lower(trim(coalesce(p.access_status, 'approved'))) <> 'rejected'\r\n    );\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "is_current_user_admin",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.is_own_student(p_student_id text)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_uid uuid := auth.uid();\r\n  v_target text := NULLIF(trim(COALESCE(p_student_id, '')), '');\r\n  v_email text;\r\n  v_linked_sid text;\r\nBEGIN\r\n  IF v_uid IS NULL OR v_target IS NULL THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  v_linked_sid := public.current_student_id_text();\r\n  IF v_linked_sid = v_target THEN\r\n    RETURN true;\r\n  END IF;\r\n\r\n  SELECT lower(trim(COALESCE(p.email, ''))) INTO v_email\r\n  FROM public.profiles p\r\n  WHERE p.id = v_uid\r\n  LIMIT 1;\r\n\r\n  RETURN EXISTS (\r\n    SELECT 1\r\n    FROM public.students s\r\n    WHERE s.id::text = v_target\r\n      AND (\r\n        NULLIF(to_jsonb(s)->>'profile_id', '') = v_uid::text\r\n        OR (COALESCE(v_email, '') <> '' AND lower(trim(COALESCE(s.email, ''))) = v_email)\r\n      )\r\n  );\r\nEND;\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "is_own_student",
            "identity_args": "p_student_id text",
            "config_settings": [
                "search_path=public, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.is_own_student_record(p_student_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.profiles p\r\n    JOIN public.students s ON s.id = p_student_id\r\n    WHERE (\r\n      p.id = auth.uid()\r\n      OR (\r\n        COALESCE(auth.jwt() ->> 'email', '') <> ''\r\n        AND lower(trim(COALESCE(p.email, ''))) = lower(trim(auth.jwt() ->> 'email'))\r\n      )\r\n    )\r\n    AND COALESCE(p.access, p.active, false) = true\r\n    AND (\r\n      p.student_id = s.id\r\n      OR s.profile_id = p.id\r\n      OR LOWER(TRIM(COALESCE(s.email, ''))) = LOWER(TRIM(COALESCE(p.email, '')))\r\n    )\r\n  );\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "is_own_student_record",
            "identity_args": "p_student_id uuid",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.is_own_teacher(p_teacher_id text)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_uid uuid := auth.uid();\r\n  v_target text := NULLIF(trim(COALESCE(p_teacher_id, '')), '');\r\n  v_email text;\r\n  v_linked_tid text;\r\nBEGIN\r\n  IF v_uid IS NULL OR v_target IS NULL THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  v_linked_tid := public.current_teacher_id_text();\r\n  IF v_linked_tid = v_target THEN\r\n    RETURN true;\r\n  END IF;\r\n\r\n  SELECT lower(trim(COALESCE(p.email, ''))) INTO v_email\r\n  FROM public.profiles p\r\n  WHERE p.id = v_uid\r\n  LIMIT 1;\r\n\r\n  RETURN EXISTS (\r\n    SELECT 1\r\n    FROM public.teachers tc\r\n    WHERE tc.id::text = v_target\r\n      AND (\r\n        NULLIF(to_jsonb(tc)->>'profile_id', '') = v_uid::text\r\n        OR (COALESCE(v_email, '') <> '' AND lower(trim(COALESCE(tc.email, ''))) = v_email)\r\n      )\r\n  );\r\nEND;\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "is_own_teacher",
            "identity_args": "p_teacher_id text",
            "config_settings": [
                "search_path=public, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.is_student_enrolled_in_activity(p_activity_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\n  SELECT public.is_active_user() AND EXISTS (\r\n    SELECT 1\r\n    FROM public.student_enrollments se\r\n    WHERE se.activity_id = p_activity_id\r\n      AND se.student_id = public.current_student_id()\r\n      AND se.active IS DISTINCT FROM false\r\n      AND se.deleted_at IS NULL\r\n      AND coalesce(se.status, 'active') NOT IN ('inactive', 'rejected')\r\n  );\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "is_student_enrolled_in_activity",
            "identity_args": "p_activity_id uuid",
            "config_settings": [
                "search_path=public, auth, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.is_student_owner(target_student_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.students s\r\n    WHERE s.id = target_student_id\r\n      AND (\r\n        s.profile_id = auth.uid()\r\n        OR lower(COALESCE(s.email, '')) = lower(COALESCE(auth.jwt() ->> 'email', ''))\r\n        OR EXISTS (\r\n          SELECT 1\r\n          FROM public.profiles p\r\n          WHERE p.id = auth.uid()\r\n            AND p.student_id = target_student_id\r\n        )\r\n      )\r\n  );\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "is_student_owner",
            "identity_args": "target_student_id uuid",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.is_teacher()\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_uid uuid := auth.uid();\r\n  v_prof public.profiles%ROWTYPE;\r\n  v_role text;\r\n  v_op_role text;\r\nBEGIN\r\n  IF v_uid IS NULL OR NOT public.is_approved_user() THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  IF public.current_teacher_id_text() IS NOT NULL THEN\r\n    RETURN true;\r\n  END IF;\r\n\r\n  SELECT * INTO v_prof\r\n  FROM public.profiles\r\n  WHERE id = v_uid\r\n  LIMIT 1;\r\n\r\n  IF NOT FOUND THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  v_role := lower(trim(COALESCE(v_prof.role::text, '')));\r\n  v_op_role := lower(trim(COALESCE(v_prof.operational_role::text, '')));\r\n\r\n  RETURN v_role IN ('teacher', 'profesor', 'monitor', 'hibrido', 'hybrid')\r\n      OR v_op_role IN ('teacher', 'profesor', 'monitor', 'hibrido', 'hybrid');\r\nEND;\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "is_teacher",
            "identity_args": "",
            "config_settings": [
                "search_path=public, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.is_teacher_of_activity(p_activity_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\n  SELECT public.is_active_user() AND EXISTS (\r\n    SELECT 1\r\n    FROM public.activities a\r\n    WHERE a.id = p_activity_id\r\n      AND a.teacher_id = public.current_teacher_id()\r\n  );\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "is_teacher_of_activity",
            "identity_args": "p_activity_id uuid",
            "config_settings": [
                "search_path=public, auth, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.is_triskell_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\n  SELECT public.is_admin();\r\n$function$\n",
            "return_type": "boolean",
