        {
            "definition": "CREATE OR REPLACE FUNCTION public.is_triskell_staff()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\n  SELECT\r\n    lower(trim(COALESCE(auth.jwt() ->> 'email', ''))) = 'cristino.conde@actriskell.org'\r\n    OR EXISTS (\r\n      SELECT 1\r\n      FROM public.profiles p\r\n      WHERE p.id = auth.uid()\r\n        AND COALESCE(p.access, p.active, false) = true\r\n        AND p.role IN ('admin', 'teacher', 'hybrid')\r\n    )\r\n    OR EXISTS (\r\n      SELECT 1\r\n      FROM public.teachers t\r\n      WHERE lower(trim(COALESCE(t.email, ''))) = lower(trim(COALESCE(auth.jwt() ->> 'email', '')))\r\n        AND t.active = true\r\n    );\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "is_triskell_staff",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.moderate_activity_unenrollment(p_student_id uuid, p_activity_id uuid, p_approve boolean, p_debts_checked boolean DEFAULT false, p_materials_checked boolean DEFAULT false, p_notes text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_updated int := 0;\r\nBEGIN\r\n  IF auth.uid() IS NULL OR NOT (public.is_admin() OR public.is_teacher_of_activity(p_activity_id)) THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Permisos insuficientes para moderar esta baja.');\r\n  END IF;\r\n\r\n  IF p_approve THEN\r\n    IF NOT (coalesce(p_debts_checked, false) AND coalesce(p_materials_checked, false)) THEN\r\n      RETURN jsonb_build_object('success', false, 'error', 'Debes verificar deudas y materiales antes de aprobar la baja.');\r\n    END IF;\r\n\r\n    UPDATE public.student_enrollments\r\n    SET active = false,\r\n        status = 'inactive',\r\n        deleted_at = now(),\r\n        ended_at = CURRENT_DATE\r\n    WHERE student_id = p_student_id\r\n      AND activity_id = p_activity_id\r\n      AND status IN ('pending_unenroll', 'pending_withdrawal');\r\n  ELSE\r\n    UPDATE public.student_enrollments\r\n    SET status = 'active',\r\n        drop_requested_at = NULL,\r\n        drop_reason = NULL\r\n    WHERE student_id = p_student_id\r\n      AND activity_id = p_activity_id\r\n      AND status IN ('pending_unenroll', 'pending_withdrawal');\r\n  END IF;\r\n\r\n  GET DIAGNOSTICS v_updated = ROW_COUNT;\r\n  IF v_updated = 0 THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Solicitud de baja no encontrada o ya procesada.');\r\n  END IF;\r\n\r\n  RETURN jsonb_build_object('success', true);\r\nEND;\r\n$function$\n",
            "return_type": "jsonb",
            "function_name": "moderate_activity_unenrollment",
            "identity_args": "p_student_id uuid, p_activity_id uuid, p_approve boolean, p_debts_checked boolean, p_materials_checked boolean, p_notes text",
            "config_settings": [
                "search_path=public, auth, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.prevent_cancel_closed_class_absence()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_is_closed boolean := false;\r\n  v_is_staff boolean := false;\r\nBEGIN\r\n  IF OLD.status IS DISTINCT FROM 'cancelled' AND NEW.status = 'cancelled' THEN\r\n    SELECT EXISTS (\r\n      SELECT 1\r\n      FROM public.profiles p\r\n      WHERE p.id = auth.uid()\r\n        AND COALESCE(p.access, p.active, false) = true\r\n        AND p.role IN ('admin', 'teacher', 'hybrid')\r\n    ) INTO v_is_staff;\r\n\r\n    SELECT coalesce(bool_or(cs.is_closed), false)\r\n      INTO v_is_closed\r\n      FROM public.class_sessions cs\r\n     WHERE cs.activity_id = OLD.activity_id\r\n       AND cs.date = OLD.session_date;\r\n\r\n    IF v_is_closed AND NOT v_is_staff THEN\r\n      RAISE EXCEPTION 'No se puede anular el aviso de ausencia porque la clase ya ha sido cerrada por el monitor.';\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "prevent_cancel_closed_class_absence",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.prevent_profile_privilege_escalation()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  is_service boolean;\r\nBEGIN\r\n  is_service := auth.uid() IS NULL\r\n    OR current_user IN ('postgres', 'supabase_admin', 'service_role')\r\n    OR COALESCE(current_setting('request.jwt.claim.role', true), '') = 'service_role'\r\n    OR COALESCE(current_setting('app.allow_profile_role_sync', true), '') = 'on';\r\n\r\n  IF is_service OR public.is_admin() THEN\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  IF NEW.role IS DISTINCT FROM OLD.role\r\n     OR NEW.access IS DISTINCT FROM OLD.access\r\n     OR NEW.active IS DISTINCT FROM OLD.active\r\n     OR NEW.access_status IS DISTINCT FROM OLD.access_status\r\n     OR NEW.approval_status IS DISTINCT FROM OLD.approval_status\r\n     OR NEW.teacher_id IS DISTINCT FROM OLD.teacher_id\r\n     OR NEW.student_id IS DISTINCT FROM OLD.student_id THEN\r\n    RAISE EXCEPTION 'Solo la administración puede modificar el rol o los vínculos de perfil.';\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "prevent_profile_privilege_escalation",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.protect_profile_auth_columns()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nBEGIN\r\n  IF lower(trim(COALESCE(OLD.email, NEW.email, ''))) = 'cristino.conde@actriskell.org' THEN\r\n    NEW.role := 'admin';\r\n    NEW.access := true;\r\n    NEW.active := true;\r\n    NEW.approval_status := 'approved';\r\n    NEW.end_date := NULL;\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  IF NEW.access IS DISTINCT FROM OLD.access THEN\r\n    NEW.active := NEW.access;\r\n  ELSIF NEW.active IS DISTINCT FROM OLD.active THEN\r\n    NEW.access := NEW.active;\r\n  END IF;\r\n\r\n  IF COALESCE(NEW.access, false) = true THEN\r\n    NEW.approval_status := 'approved';\r\n    NEW.end_date := NULL;\r\n    IF NEW.role IS NULL OR btrim(NEW.role) = '' THEN\r\n      NEW.role := 'member';\r\n    END IF;\r\n  ELSIF NEW.approval_status IS NULL THEN\r\n    NEW.approval_status := CASE WHEN NEW.end_date IS NOT NULL THEN 'rejected' ELSE 'pending' END;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "protect_profile_auth_columns",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.protect_profile_privileged_columns()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\nBEGIN\r\n  IF current_setting('app.bypass_profile_guard', true) = 'on'\r\n     OR auth.role() = 'service_role'\r\n     OR public.is_admin() THEN\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  NEW.role             := OLD.role;\r\n  NEW.operational_role := OLD.operational_role;\r\n  NEW.access           := OLD.access;\r\n  NEW.active           := OLD.active;\r\n  NEW.access_status    := OLD.access_status;\r\n  NEW.approval_status  := OLD.approval_status;\r\n  NEW.is_socio         := OLD.is_socio;\r\n  NEW.member_type      := OLD.member_type;\r\n  NEW.member_number    := OLD.member_number;\r\n  NEW.teacher_id       := OLD.teacher_id;\r\n  NEW.student_id       := OLD.student_id;\r\n  NEW.start_date       := OLD.start_date;\r\n  NEW.end_date         := OLD.end_date;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "protect_profile_privileged_columns",
            "identity_args": "",
            "config_settings": [
                "search_path=public, auth, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.protect_profile_privileged_fields()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_uid uuid := auth.uid();\r\nBEGIN\r\n  IF v_uid IS NULL\r\n     OR current_setting('app.allow_profile_role_sync', true) = 'on'\r\n     OR pg_trigger_depth() > 1\r\n     OR public.is_admin() THEN\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  IF NEW.role IS DISTINCT FROM OLD.role\r\n     OR NEW.active IS DISTINCT FROM OLD.active\r\n     OR NEW.access IS DISTINCT FROM OLD.access\r\n     OR NEW.operational_role IS DISTINCT FROM OLD.operational_role\r\n     OR NEW.is_socio IS DISTINCT FROM OLD.is_socio\r\n     OR NEW.member_type IS DISTINCT FROM OLD.member_type\r\n     OR NEW.member_number IS DISTINCT FROM OLD.member_number\r\n     OR NEW.student_id IS DISTINCT FROM OLD.student_id\r\n     OR NEW.teacher_id IS DISTINCT FROM OLD.teacher_id THEN\r\n    RAISE EXCEPTION 'Solo la administración puede modificar el estado de acceso, rol, número de socio o vínculos.'\r\n      USING ERRCODE = '42501';\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "protect_profile_privileged_fields",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.quick_create_and_enroll_student(p_name text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_activity_id uuid DEFAULT NULL::uuid, p_custom_price numeric DEFAULT NULL::numeric)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_student_id uuid;\r\n  v_clean_email text := nullif(lower(trim(coalesce(p_email, ''))), '');\r\n  v_clean_name text := trim(coalesce(p_name, ''));\r\nBEGIN\r\n  IF p_activity_id IS NULL THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'El taller es obligatorio.');\r\n  END IF;\r\n\r\n  IF auth.uid() IS NULL OR NOT (public.is_admin() OR public.is_teacher_of_activity(p_activity_id)) THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Permisos insuficientes para crear/matricular en este taller.');\r\n  END IF;\r\n\r\n  IF v_clean_name = '' THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'El nombre del alumno es obligatorio.');\r\n  END IF;\r\n\r\n  IF v_clean_email IS NOT NULL THEN\r\n    SELECT s.id INTO v_student_id\r\n    FROM public.students s\r\n    WHERE lower(trim(s.email)) = v_clean_email\r\n    LIMIT 1;\r\n  END IF;\r\n\r\n  IF v_student_id IS NULL THEN\r\n    INSERT INTO public.students (\r\n      name, email, phone, status, validation_status,\r\n      registered_at, registered_by, notes, member_type, start_date\r\n    ) VALUES (\r\n      v_clean_name,\r\n      v_clean_email,\r\n      nullif(trim(coalesce(p_phone, '')), ''),\r\n      'pending_validation',\r\n      'pending',\r\n      CURRENT_DATE,\r\n      auth.uid(),\r\n      nullif(trim(coalesce(p_notes, '')), ''),\r\n      'socio',\r\n      CURRENT_DATE\r\n    )\r\n    RETURNING id INTO v_student_id;\r\n  END IF;\r\n\r\n  INSERT INTO public.student_enrollments (\r\n    student_id, activity_id, custom_price, billing_mode, enrolled_since, status, active\r\n  ) VALUES (\r\n    v_student_id,\r\n    p_activity_id,\r\n    p_custom_price,\r\n    coalesce((SELECT billing_mode FROM public.activities WHERE id = p_activity_id), 'monthly'),\r\n    CURRENT_DATE,\r\n    'active',\r\n    true\r\n  )\r\n  ON CONFLICT (student_id, activity_id) DO UPDATE SET\r\n    active = true,\r\n    status = 'active',\r\n    deleted_at = NULL,\r\n    ended_at = NULL,\r\n    custom_price = coalesce(EXCLUDED.custom_price, public.student_enrollments.custom_price);\r\n\r\n  RETURN jsonb_build_object('success', true, 'student_id', v_student_id);\r\nEND;\r\n$function$\n",
            "return_type": "jsonb",
            "function_name": "quick_create_and_enroll_student",
            "identity_args": "p_name text, p_email text, p_phone text, p_notes text, p_activity_id uuid, p_custom_price numeric",
            "config_settings": [
                "search_path=public, auth, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.reevaluate_user_operational_role(p_profile_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_prof public.profiles%ROWTYPE;\r\n  v_has_student boolean := false;\r\n  v_has_teacher boolean := false;\r\n  v_next_op text := 'vacio';\r\n  v_next_role text;\r\nBEGIN\r\n  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'No autorizado.');\r\n  END IF;\r\n\r\n  IF NOT (public.is_admin() OR p_profile_id = auth.uid() OR public.current_teacher_id() IS NOT NULL) THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Permisos insuficientes.');\r\n  END IF;\r\n\r\n  SELECT * INTO v_prof FROM public.profiles WHERE id = p_profile_id;\r\n  IF NOT FOUND THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Perfil no encontrado.');\r\n  END IF;\r\n\r\n  IF lower(trim(v_prof.role)) IN ('admin', 'administrador', 'administrator') THEN\r\n    RETURN jsonb_build_object('success', true, 'preserved_admin', true);\r\n  END IF;\r\n\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.students s\r\n    JOIN public.student_enrollments se ON se.student_id = s.id\r\n    JOIN public.activities a ON a.id = se.activity_id\r\n    WHERE (s.id = v_prof.student_id OR s.profile_id = v_prof.id OR lower(trim(s.email)) = lower(trim(v_prof.email)))\r\n      AND coalesce(s.status, 'active') NOT IN ('inactive', 'pending_validation', 'pending')\r\n      AND se.active IS DISTINCT FROM false\r\n      AND se.deleted_at IS NULL\r\n      AND coalesce(se.status, 'active') NOT IN ('pending', 'pending_enrollment', 'rejected', 'inactive')\r\n      AND a.active IS DISTINCT FROM false\r\n  ) INTO v_has_student;\r\n\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.teachers t\r\n    JOIN public.activities a ON a.teacher_id = t.id\r\n    WHERE (t.id = v_prof.teacher_id OR lower(trim(t.email)) = lower(trim(v_prof.email)))\r\n      AND t.active IS DISTINCT FROM false\r\n      AND a.active IS DISTINCT FROM false\r\n  ) INTO v_has_teacher;\r\n\r\n  IF v_has_teacher AND v_has_student THEN\r\n    v_next_op := 'hibrido';\r\n    v_next_role := 'Híbrido';\r\n  ELSIF v_has_teacher THEN\r\n    v_next_op := 'profesor';\r\n    v_next_role := 'Monitor';\r\n  ELSIF v_has_student THEN\r\n    v_next_op := 'alumno';\r\n    v_next_role := 'Alumno';\r\n  ELSE\r\n    v_next_op := 'vacio';\r\n    v_next_role := CASE WHEN coalesce(v_prof.is_socio, true) THEN 'Socio' ELSE v_prof.role END;\r\n  END IF;\r\n\r\n  PERFORM set_config('app.bypass_profile_guard', 'on', true);\r\n  UPDATE public.profiles\r\n  SET operational_role = v_next_op,\r\n      role = coalesce(v_next_role, role)\r\n  WHERE id = p_profile_id;\r\n\r\n  RETURN jsonb_build_object('success', true, 'operational_role', v_next_op, 'role', v_next_role);\r\nEND;\r\n$function$\n",
            "return_type": "jsonb",
            "function_name": "reevaluate_user_operational_role",
            "identity_args": "p_profile_id uuid",
            "config_settings": [
                "search_path=public, auth, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.reject_association_withdrawal(p_request_id uuid, p_notes text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_updated int := 0;\r\nBEGIN\r\n  IF auth.uid() IS NULL OR NOT public.is_admin() THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Solo administración puede rechazar bajas de asociación.');\r\n  END IF;\r\n\r\n  UPDATE public.membership_withdrawal_requests\r\n  SET status = 'rejected',\r\n      debts_checked = false,\r\n      materials_checked = false,\r\n      resolution_notes = nullif(trim(coalesce(p_notes, '')), ''),\r\n      resolved_by = auth.uid(),\r\n      resolved_at = now(),\r\n      updated_at = now()\r\n  WHERE id = p_request_id AND status = 'pending';\r\n\r\n  GET DIAGNOSTICS v_updated = ROW_COUNT;\r\n  IF v_updated = 0 THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Solicitud no encontrada o ya resuelta.');\r\n  END IF;\r\n\r\n  RETURN jsonb_build_object('success', true);\r\nEND;\r\n$function$\n",
            "return_type": "jsonb",
            "function_name": "reject_association_withdrawal",
            "identity_args": "p_request_id uuid, p_notes text",
            "config_settings": [
                "search_path=public, auth, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.request_activity_unenrollment(p_activity_id uuid, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_student_id uuid;\r\n  v_updated int := 0;\r\nBEGIN\r\n  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Sesión no autorizada.');\r\n  END IF;\r\n\r\n  v_student_id := public.current_student_id();\r\n  IF v_student_id IS NULL THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'No tienes ficha de alumno vinculada.');\r\n  END IF;\r\n\r\n  UPDATE public.student_enrollments\r\n  SET status = 'pending_unenroll',\r\n      drop_requested_at = now(),\r\n      drop_reason = nullif(trim(coalesce(p_reason, '')), '')\r\n  WHERE student_id = v_student_id\r\n    AND activity_id = p_activity_id\r\n    AND active IS DISTINCT FROM false\r\n    AND coalesce(status, 'active') IN ('active', 'approved');\r\n\r\n  GET DIAGNOSTICS v_updated = ROW_COUNT;\r\n  IF v_updated = 0 THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'No hay matrícula activa eligible para solicitar baja.');\r\n  END IF;\r\n\r\n  RETURN jsonb_build_object('success', true);\r\nEND;\r\n$function$\n",
            "return_type": "jsonb",
            "function_name": "request_activity_unenrollment",
            "identity_args": "p_activity_id uuid, p_reason text",
            "config_settings": [
                "search_path=public, auth, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.self_unenroll_from_activity(p_activity_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_student_id uuid;\r\n  v_updated int := 0;\r\nBEGIN\r\n  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Sesión no autorizada.');\r\n  END IF;\r\n\r\n  v_student_id := public.current_student_id();\r\n  IF v_student_id IS NULL THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'No tienes ficha de alumno vinculada.');\r\n  END IF;\r\n\r\n  UPDATE public.student_enrollments\r\n  SET active = false,\r\n      status = 'inactive',\r\n      deleted_at = now(),\r\n      ended_at = CURRENT_DATE\r\n  WHERE student_id = v_student_id\r\n    AND activity_id = p_activity_id\r\n    AND active IS DISTINCT FROM false;\r\n\r\n  GET DIAGNOSTICS v_updated = ROW_COUNT;\r\n  IF v_updated = 0 THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'No existe matrícula activa para dar de baja.');\r\n  END IF;\r\n\r\n  RETURN jsonb_build_object('success', true);\r\nEND;\r\n$function$\n",
            "return_type": "jsonb",
            "function_name": "self_unenroll_from_activity",
            "identity_args": "p_activity_id uuid",
            "config_settings": [
                "search_path=public, auth, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
