        {
            "definition": "CREATE OR REPLACE FUNCTION public.student_is_enrolled_in_activity(p_activity_id text)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_target text := NULLIF(trim(COALESCE(p_activity_id, '')), '');\r\nBEGIN\r\n  IF auth.uid() IS NULL OR v_target IS NULL THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  RETURN EXISTS (\r\n    SELECT 1\r\n    FROM public.student_enrollments se\r\n    WHERE se.activity_id::text = v_target\r\n      AND public.is_own_student(se.student_id::text)\r\n      AND COALESCE(se.active, true) = true\r\n      AND COALESCE(se.status::text, 'active') NOT IN ('inactive', 'rejected')\r\n  );\r\nEND;\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "student_is_enrolled_in_activity",
            "identity_args": "p_activity_id text",
            "config_settings": [
                "search_path=public, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.student_shares_teacher(p_teacher_id text)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_target text := NULLIF(trim(COALESCE(p_teacher_id, '')), '');\r\nBEGIN\r\n  IF auth.uid() IS NULL OR v_target IS NULL THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  RETURN EXISTS (\r\n    SELECT 1\r\n    FROM public.student_enrollments se\r\n    JOIN public.activities a ON a.id::text = se.activity_id::text\r\n    WHERE a.teacher_id::text = v_target\r\n      AND public.is_own_student(se.student_id::text)\r\n  );\r\nEND;\r\n$function$\n",
            "return_type": "boolean",
