            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.sync_profile_on_student_link()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nBEGIN\r\n  IF NEW.profile_id IS NOT NULL THEN\r\n    PERFORM set_config('app.allow_profile_role_sync', 'on', true);\r\n    UPDATE public.profiles\r\n    SET\r\n      student_id = NEW.id,\r\n      role = CASE\r\n        WHEN role = 'teacher' THEN 'hybrid'\r\n        ELSE role\r\n      END,\r\n      updated_at = NOW()\r\n    WHERE id = NEW.profile_id;\r\n    PERFORM set_config('app.allow_profile_role_sync', 'off', true);\r\n  END IF;\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "sync_profile_on_student_link",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.sync_profile_role_and_access(p_profile_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_prof public.profiles%ROWTYPE;\r\n  v_op_role public.operational_role_type;\r\n  v_is_socio boolean;\r\n  v_next_role text;\r\n  v_next_active boolean;\r\n  v_next_end_date date;\r\nBEGIN\r\n  SELECT * INTO v_prof FROM public.profiles WHERE id = p_profile_id;\r\n  IF NOT FOUND THEN\r\n    RETURN jsonb_build_object('updated', false, 'reason', 'profile_not_found');\r\n  END IF;\r\n\r\n  v_op_role := public.derive_user_operational_role(\r\n    v_prof.student_id,\r\n    v_prof.teacher_id,\r\n    v_prof.email,\r\n    v_prof.id\r\n  );\r\n  v_is_socio := coalesce(v_prof.is_socio, v_prof.member_type = 'socio', false);\r\n\r\n  IF v_prof.role IS NOT DISTINCT FROM 'admin'\r\n     OR lower(trim(coalesce(v_prof.email, ''))) = 'cristino.conde@actriskell.org' THEN\r\n    v_next_role := 'admin';\r\n    v_next_active := CASE\r\n      WHEN lower(trim(coalesce(v_prof.email, ''))) = 'cristino.conde@actriskell.org' THEN true\r\n      ELSE coalesce(v_prof.access, v_prof.active, true)\r\n    END;\r\n    v_next_end_date := CASE WHEN v_next_active THEN NULL ELSE coalesce(v_prof.end_date, current_date) END;\r\n  ELSE\r\n    CASE v_op_role\r\n      WHEN 'hibrido' THEN\r\n        v_next_role := 'hybrid';\r\n        v_next_active := coalesce(v_prof.access, v_prof.active, true);\r\n        v_next_end_date := CASE WHEN v_next_active THEN NULL ELSE coalesce(v_prof.end_date, current_date) END;\r\n      WHEN 'alumno' THEN\r\n        v_next_role := 'student';\r\n        v_next_active := coalesce(v_prof.access, v_prof.active, true);\r\n        v_next_end_date := CASE WHEN v_next_active THEN NULL ELSE coalesce(v_prof.end_date, current_date) END;\r\n      WHEN 'profesor' THEN\r\n        v_next_role := 'teacher';\r\n        v_next_active := coalesce(v_prof.access, v_prof.active, true);\r\n        v_next_end_date := CASE WHEN v_next_active THEN NULL ELSE coalesce(v_prof.end_date, current_date) END;\r\n      ELSE\r\n        IF v_is_socio THEN\r\n          v_next_role := CASE\r\n            WHEN v_prof.role IN ('teacher', 'student', 'hybrid', 'member') THEN v_prof.role\r\n            ELSE 'member'\r\n          END;\r\n          v_next_active := coalesce(v_prof.access, v_prof.active, true);\r\n          v_next_end_date := CASE WHEN v_next_active THEN NULL ELSE coalesce(v_prof.end_date, current_date) END;\r\n        ELSE\r\n          v_next_role := COALESCE(NULLIF(v_prof.role, ''), 'member');\r\n          IF v_next_role NOT IN ('admin', 'teacher', 'student', 'hybrid', 'member') THEN\r\n            v_next_role := 'member';\r\n          END IF;\r\n          v_next_active := false;\r\n          v_next_end_date := coalesce(v_prof.end_date, current_date);\r\n        END IF;\r\n    END CASE;\r\n  END IF;\r\n\r\n  PERFORM set_config('app.allow_profile_role_sync', 'on', true);\r\n\r\n  UPDATE public.profiles\r\n  SET\r\n    operational_role = v_op_role,\r\n    is_socio = v_is_socio,\r\n    role = v_next_role,\r\n    access = v_next_active,\r\n    active = v_next_active,\r\n    end_date = v_next_end_date,\r\n    member_type = CASE\r\n      WHEN v_is_socio THEN 'socio'\r\n      WHEN v_op_role = 'profesor' OR v_next_role IN ('teacher', 'hybrid') THEN 'monitor_no_socio'\r\n      ELSE 'alumno_no_socio'\r\n    END\r\n  WHERE id = p_profile_id;\r\n\r\n  PERFORM set_config('app.allow_profile_role_sync', 'off', true);\r\n\r\n  RETURN jsonb_build_object(\r\n    'profile_id', p_profile_id,\r\n    'operational_role', v_op_role,\r\n    'is_socio', v_is_socio,\r\n    'role', v_next_role,\r\n    'access', v_next_active,\r\n    'active', v_next_active\r\n  );\r\nEND;\r\n$function$\n",
            "return_type": "jsonb",
            "function_name": "sync_profile_role_and_access",
            "identity_args": "p_profile_id uuid",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.sync_student_absence_to_attendance()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_session RECORD;\r\n  v_att_id public.session_attendances.id%TYPE;\r\n  v_target_date text := left(NEW.session_date::text, 10);\r\n  v_present_count integer;\r\nBEGIN\r\n  IF NEW.status NOT IN ('reported', 'approved', 'cancelled') THEN\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  FOR v_session IN\r\n    SELECT id, COALESCE(is_closed, false) AS is_closed\r\n    FROM public.class_sessions\r\n    WHERE activity_id = NEW.activity_id\r\n      AND left(date::text, 10) = v_target_date\r\n  LOOP\r\n    IF NEW.status IN ('reported', 'cancelled') AND v_session.is_closed THEN\r\n      CONTINUE;\r\n    END IF;\r\n\r\n    SELECT id INTO v_att_id\r\n    FROM public.session_attendances\r\n    WHERE session_id = v_session.id\r\n      AND student_id = NEW.student_id\r\n    LIMIT 1;\r\n\r\n    IF NEW.status IN ('reported', 'approved') THEN\r\n      IF v_att_id IS NOT NULL THEN\r\n        UPDATE public.session_attendances\r\n        SET attendance = 'absent'\r\n        WHERE id = v_att_id;\r\n      ELSE\r\n        INSERT INTO public.session_attendances (\r\n          session_id, student_id, attendance, paid, paid_amount, payment_method, payment_id\r\n        ) VALUES (\r\n          v_session.id, NEW.student_id, 'absent', false, 0, 'cash', NULL\r\n        );\r\n      END IF;\r\n    ELSIF NEW.status = 'cancelled' THEN\r\n      IF v_att_id IS NOT NULL THEN\r\n        UPDATE public.session_attendances\r\n        SET attendance = 'present'\r\n        WHERE id = v_att_id\r\n          AND attendance = 'absent';\r\n      END IF;\r\n    END IF;\r\n\r\n    SELECT COUNT(*)::integer INTO v_present_count\r\n    FROM public.session_attendances\r\n    WHERE session_id = v_session.id\r\n      AND attendance <> 'absent';\r\n\r\n    UPDATE public.class_sessions\r\n    SET attendees_count = v_present_count\r\n    WHERE id = v_session.id;\r\n  END LOOP;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "sync_student_absence_to_attendance",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.teacher_owns_session(p_session_id text)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_tid text := public.current_teacher_id_text();\r\n  v_target text := NULLIF(trim(COALESCE(p_session_id, '')), '');\r\nBEGIN\r\n  IF v_tid IS NULL OR v_target IS NULL THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  RETURN EXISTS (\r\n    SELECT 1\r\n    FROM public.class_sessions cs\r\n    LEFT JOIN public.activities a ON a.id::text = cs.activity_id::text\r\n    WHERE cs.id::text = v_target\r\n      AND (cs.teacher_id::text = v_tid OR a.teacher_id::text = v_tid)\r\n  );\r\nEND;\r\n$function$\n",
            "return_type": "boolean",
            "function_name": "teacher_owns_session",
            "identity_args": "p_session_id text",
            "config_settings": [
                "search_path=public, pg_temp"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.teacher_teaches_activity(p_activity_id text)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_tid text := public.current_teacher_id_text();\r\n  v_target text := NULLIF(trim(COALESCE(p_activity_id, '')), '');\r\nBEGIN\r\n  IF v_tid IS NULL OR v_target IS NULL THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  RETURN EXISTS (\r\n    SELECT 1\r\n    FROM public.activities a\r\n    WHERE a.id::text = v_target\r\n      AND a.teacher_id::text = v_tid\r\n  );\r\nEND;\r\n$function$\n",
