        {
            "definition": "CREATE OR REPLACE FUNCTION public.teacher_teaches_student(p_student_id text)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_tid text := public.current_teacher_id_text();\r\n  v_target text := NULLIF(trim(COALESCE(p_student_id, '')), '');\r\nBEGIN\r\n  IF v_tid IS NULL OR v_target IS NULL THEN\r\n    RETURN false;\r\n  END IF;\r\n\r\n  RETURN EXISTS (\r\n    SELECT 1\r\n    FROM public.student_enrollments se\r\n    JOIN public.activities a ON a.id::text = se.activity_id::text\r\n    WHERE se.student_id::text = v_target\r\n      AND a.teacher_id::text = v_tid\r\n  );\r\nEND;\r\n$function$\n",
