        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.trg_fn_activities_auto_sync()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_act_id uuid := coalesce(NEW.id, OLD.id);\r\n  v_st record;\r\nBEGIN\r\n  IF pg_trigger_depth() > 1 THEN RETURN NULL; END IF;\r\n  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.teacher_id IS NOT NULL THEN\r\n    PERFORM public.trg_sync_profiles_for_teacher(NEW.teacher_id);\r\n  END IF;\r\n  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.teacher_id IS NOT NULL\r\n     AND (TG_OP = 'DELETE' OR OLD.teacher_id IS DISTINCT FROM NEW.teacher_id) THEN\r\n    PERFORM public.trg_sync_profiles_for_teacher(OLD.teacher_id);\r\n  END IF;\r\n  FOR v_st IN\r\n    SELECT DISTINCT student_id FROM public.student_enrollments WHERE activity_id = v_act_id\r\n  LOOP\r\n    PERFORM public.trg_sync_profiles_for_student(v_st.student_id);\r\n  END LOOP;\r\n  RETURN NULL;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "trg_fn_activities_auto_sync",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.trg_fn_assign_socio_member_number()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_row        JSONB := to_jsonb(NEW);\r\n  v_is_socio   BOOLEAN := COALESCE((v_row->>'is_socio')::boolean, false);\r\n  v_role       TEXT := v_row->>'role';\r\n  v_mtype      TEXT := v_row->>'member_type';\r\nBEGIN\r\n  IF NEW.member_number IS NOT NULL AND btrim(NEW.member_number) <> '' THEN\r\n    NEW.member_number := public.format_socio_member_number(NEW.member_number);\r\n  ELSIF v_is_socio OR v_role = 'socio' OR v_mtype = 'socio' THEN\r\n    NEW.member_number := lpad(nextval('public.socio_member_number_seq')::text, 5, '0');\r\n  ELSE\r\n    NEW.member_number := NULL;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "trg_fn_assign_socio_member_number",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.trg_fn_enrollments_auto_sync()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nBEGIN\r\n  IF pg_trigger_depth() > 1 THEN RETURN NULL; END IF;\r\n  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.student_id IS NOT NULL THEN\r\n    PERFORM public.trg_sync_profiles_for_student(NEW.student_id);\r\n  END IF;\r\n  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.student_id IS NOT NULL\r\n     AND (TG_OP = 'DELETE' OR OLD.student_id IS DISTINCT FROM NEW.student_id) THEN\r\n    PERFORM public.trg_sync_profiles_for_student(OLD.student_id);\r\n  END IF;\r\n  RETURN NULL;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "trg_fn_enrollments_auto_sync",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.trg_fn_profiles_auto_sync()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_op_role public.operational_role_type;\r\nBEGIN\r\n  IF pg_trigger_depth() > 1 THEN\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  IF lower(trim(COALESCE(NEW.email, ''))) = 'cristino.conde@actriskell.org' THEN\r\n    NEW.role := 'admin';\r\n    NEW.active := true;\r\n    NEW.access := true;\r\n    NEW.approval_status := 'approved';\r\n    NEW.end_date := NULL;\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  -- Si la cuenta sigue pendiente o fue rechazada/bloqueada, no otorgar acceso ni rol automático\r\n  IF COALESCE(NEW.approval_status, 'pending') IN ('pending', 'rejected')\r\n     AND COALESCE(NEW.access, NEW.active, false) = false THEN\r\n    NEW.operational_role := COALESCE(NEW.operational_role, 'vacio'::public.operational_role_type);\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  IF TG_OP = 'INSERT' OR (\r\n    NEW.is_socio IS DISTINCT FROM OLD.is_socio\r\n    OR NEW.student_id IS DISTINCT FROM OLD.student_id\r\n    OR NEW.teacher_id IS DISTINCT FROM OLD.teacher_id\r\n  ) THEN\r\n    v_op_role := public.derive_user_operational_role(NEW.student_id, NEW.teacher_id, NEW.email, NEW.id);\r\n    NEW.operational_role := v_op_role;\r\n\r\n    IF NEW.role IS DISTINCT FROM 'admin' THEN\r\n      CASE v_op_role\r\n        WHEN 'hibrido' THEN\r\n          NEW.role := 'hybrid';\r\n          NEW.active := true;\r\n          NEW.access := true;\r\n          NEW.approval_status := 'approved';\r\n          NEW.end_date := NULL;\r\n        WHEN 'alumno' THEN\r\n          NEW.role := 'student';\r\n          NEW.active := true;\r\n          NEW.access := true;\r\n          NEW.approval_status := 'approved';\r\n          NEW.end_date := NULL;\r\n        WHEN 'profesor' THEN\r\n          NEW.role := 'teacher';\r\n          NEW.active := true;\r\n          NEW.access := true;\r\n          NEW.approval_status := 'approved';\r\n          NEW.end_date := NULL;\r\n        ELSE\r\n          IF COALESCE(NEW.access, NEW.active, false) = true THEN\r\n            NEW.role := COALESCE(NULLIF(NEW.role, ''), 'member');\r\n            NEW.approval_status := 'approved';\r\n          END IF;\r\n      END CASE;\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "trg_fn_profiles_auto_sync",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.trg_fn_students_auto_sync()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nBEGIN\r\n  IF pg_trigger_depth() > 1 THEN RETURN NULL; END IF;\r\n  IF NEW.is_socio IS DISTINCT FROM OLD.is_socio THEN\r\n    UPDATE public.profiles\r\n    SET is_socio = NEW.is_socio\r\n    WHERE student_id = NEW.id\r\n       OR (NEW.profile_id IS NOT NULL AND id = NEW.profile_id)\r\n       OR (coalesce(trim(NEW.email), '') <> '' AND lower(trim(email)) = lower(trim(NEW.email)));\r\n  END IF;\r\n  PERFORM public.trg_sync_profiles_for_student(NEW.id);\r\n  RETURN NULL;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "trg_fn_students_auto_sync",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.trg_fn_sync_profile_member_number()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nBEGIN\r\n  IF pg_trigger_depth() > 1 THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  IF TG_OP = 'INSERT' OR NEW.member_number IS DISTINCT FROM OLD.member_number THEN\r\n    IF NEW.student_id IS NOT NULL THEN\r\n      UPDATE public.students\r\n      SET member_number = NEW.member_number\r\n      WHERE id = NEW.student_id\r\n        AND member_number IS DISTINCT FROM NEW.member_number;\r\n    END IF;\r\n\r\n    IF NEW.teacher_id IS NOT NULL THEN\r\n      UPDATE public.teachers\r\n      SET member_number = NEW.member_number\r\n      WHERE id = NEW.teacher_id\r\n        AND member_number IS DISTINCT FROM NEW.member_number;\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN NULL;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "trg_fn_sync_profile_member_number",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.trg_fn_teachers_auto_sync()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nBEGIN\r\n  IF pg_trigger_depth() > 1 THEN RETURN NULL; END IF;\r\n  IF NEW.is_socio IS DISTINCT FROM OLD.is_socio THEN\r\n    UPDATE public.profiles\r\n    SET is_socio = NEW.is_socio\r\n    WHERE teacher_id = NEW.id\r\n       OR (coalesce(trim(NEW.email), '') <> '' AND lower(trim(email)) = lower(trim(NEW.email)));\r\n  END IF;\r\n  PERFORM public.trg_sync_profiles_for_teacher(NEW.id);\r\n  RETURN NULL;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "trg_fn_teachers_auto_sync",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.trg_reevaluate_role_from_activity()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_act_id  UUID;\r\n  v_prof_id UUID;\r\nBEGIN\r\n  IF pg_trigger_depth() > 1 THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  v_act_id := COALESCE(NEW.id, OLD.id);\r\n\r\n  -- Reevaluar profesor anterior y/o nuevo\r\n  FOR v_prof_id IN\r\n    SELECT DISTINCT p.id\r\n    FROM public.profiles p\r\n    LEFT JOIN public.teachers t ON t.id IN (OLD.teacher_id, NEW.teacher_id)\r\n    WHERE p.teacher_id IN (OLD.teacher_id, NEW.teacher_id)\r\n       OR (\r\n         t.email IS NOT NULL\r\n         AND btrim(t.email) <> ''\r\n         AND lower(btrim(p.email)) = lower(btrim(t.email))\r\n       )\r\n  LOOP\r\n    PERFORM public.reevaluate_user_operational_role(v_prof_id);\r\n  END LOOP;\r\n\r\n  -- Si cambió active o se eliminó el taller, reevaluar también alumnos inscritos\r\n  IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND COALESCE(OLD.active, TRUE) IS DISTINCT FROM COALESCE(NEW.active, TRUE)) THEN\r\n    FOR v_prof_id IN\r\n      SELECT DISTINCT p.id\r\n      FROM public.student_enrollments se\r\n      JOIN public.students s ON s.id = se.student_id\r\n      JOIN public.profiles p\r\n        ON p.student_id = s.id\r\n        OR (s.profile_id IS NOT NULL AND p.id = s.profile_id)\r\n        OR (\r\n          s.email IS NOT NULL\r\n          AND btrim(s.email) <> ''\r\n          AND lower(btrim(p.email)) = lower(btrim(s.email))\r\n        )\r\n      WHERE se.activity_id = v_act_id\r\n    LOOP\r\n      PERFORM public.reevaluate_user_operational_role(v_prof_id);\r\n    END LOOP;\r\n  END IF;\r\n\r\n  RETURN NULL;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "trg_reevaluate_role_from_activity",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.trg_reevaluate_role_from_enrollment()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_student_id UUID;\r\n  v_prof_id    UUID;\r\nBEGIN\r\n  IF pg_trigger_depth() > 1 THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  v_student_id := COALESCE(NEW.student_id, OLD.student_id);\r\n  IF v_student_id IS NULL THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  FOR v_prof_id IN\r\n    SELECT DISTINCT p.id\r\n    FROM public.profiles p\r\n    LEFT JOIN public.students s ON s.id = v_student_id\r\n    WHERE p.student_id = v_student_id\r\n       OR (s.profile_id IS NOT NULL AND p.id = s.profile_id)\r\n       OR (\r\n         s.email IS NOT NULL\r\n         AND btrim(s.email) <> ''\r\n         AND lower(btrim(p.email)) = lower(btrim(s.email))\r\n       )\r\n  LOOP\r\n    PERFORM public.reevaluate_user_operational_role(v_prof_id);\r\n  END LOOP;\r\n\r\n  RETURN NULL;\r\nEND;\r\n$function$\n",
            "return_type": "trigger",
            "function_name": "trg_reevaluate_role_from_enrollment",
            "identity_args": "",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.trg_sync_profiles_for_student(p_student_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_email text;\r\n  v_profile_id uuid;\r\n  v_rec record;\r\nBEGIN\r\n  SELECT email, profile_id INTO v_email, v_profile_id\r\n  FROM public.students WHERE id = p_student_id;\r\n\r\n  FOR v_rec IN\r\n    SELECT DISTINCT id FROM public.profiles\r\n    WHERE student_id = p_student_id\r\n       OR (v_profile_id IS NOT NULL AND id = v_profile_id)\r\n       OR (coalesce(trim(v_email), '') <> '' AND lower(trim(email)) = lower(trim(v_email)))\r\n  LOOP\r\n    PERFORM public.sync_profile_role_and_access(v_rec.id);\r\n  END LOOP;\r\nEND;\r\n$function$\n",
            "return_type": "void",
            "function_name": "trg_sync_profiles_for_student",
            "identity_args": "p_student_id uuid",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
        {
            "definition": "CREATE OR REPLACE FUNCTION public.trg_sync_profiles_for_teacher(p_teacher_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_email text;\r\n  v_rec record;\r\nBEGIN\r\n  SELECT email INTO v_email FROM public.teachers WHERE id = p_teacher_id;\r\n\r\n  FOR v_rec IN\r\n    SELECT DISTINCT id FROM public.profiles\r\n    WHERE teacher_id = p_teacher_id\r\n       OR (coalesce(trim(v_email), '') <> '' AND lower(trim(email)) = lower(trim(v_email)))\r\n  LOOP\r\n    PERFORM public.sync_profile_role_and_access(v_rec.id);\r\n  END LOOP;\r\nEND;\r\n$function$\n",
            "return_type": "void",
            "function_name": "trg_sync_profiles_for_teacher",
            "identity_args": "p_teacher_id uuid",
            "config_settings": [
                "search_path=public"
            ],
            "anon_can_execute": true,
            "is_security_definer": true,
            "authenticated_can_execute": true
        },
