    "triggers_public_and_auth_users": [
        {
            "level": "ROW",
            "events": "INSERT",
            "timing": "AFTER",
            "target_table": "auth.users",
            "trigger_name": "on_auth_user_created",
            "enabled_state": "O",
            "function_name": "public.handle_new_user",
            "function_definition": "CREATE OR REPLACE FUNCTION public.handle_new_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_email text;\r\n  v_full_name text;\r\n  v_avatar_url text;\r\n  v_is_master boolean;\r\n  v_raw_role text;\r\n  v_role text;\r\n  v_access boolean;\r\n  v_is_socio boolean;\r\n  v_status text;\r\nBEGIN\r\n  v_email := lower(trim(COALESCE(NEW.email, '')));\r\n  v_is_master := (v_email = 'cristino.conde@actriskell.org');\r\n\r\n  v_full_name := COALESCE(\r\n    NULLIF(trim(NEW.raw_user_meta_data ->> 'full_name'), ''),\r\n    NULLIF(trim(NEW.raw_user_meta_data ->> 'name'), ''),\r\n    NULLIF(trim(concat_ws(' ', NEW.raw_user_meta_data ->> 'given_name', NEW.raw_user_meta_data ->> 'family_name')), ''),\r\n    NULLIF(trim(concat_ws(' ', NEW.raw_user_meta_data ->> 'first_name', NEW.raw_user_meta_data ->> 'last_name')), ''),\r\n    NULLIF(split_part(v_email, '@', 1), ''),\r\n    'Usuario'\r\n  );\r\n\r\n  IF lower(trim(v_full_name)) IN ('aaa', 'usuario', 'user', 'sin nombre', 'no name', 'placeholder', 'test') THEN\r\n    v_full_name := COALESCE(NULLIF(split_part(v_email, '@', 1), ''), v_full_name);\r\n  END IF;\r\n\r\n  v_avatar_url := COALESCE(\r\n    NULLIF(trim(NEW.raw_user_meta_data ->> 'avatar_url'), ''),\r\n    NULLIF(trim(NEW.raw_user_meta_data ->> 'picture'), '')\r\n  );\r\n\r\n  IF v_is_master THEN\r\n    v_role := 'admin';\r\n    v_access := true;\r\n    v_is_socio := COALESCE((NEW.raw_user_meta_data ->> 'is_socio')::boolean, true);\r\n    v_status := 'approved';\r\n  ELSE\r\n    v_raw_role := lower(trim(COALESCE(NEW.raw_user_meta_data ->> 'role', '')));\r\n    v_role := CASE v_raw_role\r\n      WHEN 'admin' THEN 'admin'\r\n      WHEN 'administrador' THEN 'admin'\r\n      WHEN 'monitor' THEN 'teacher'\r\n      WHEN 'teacher' THEN 'teacher'\r\n      WHEN 'profesor' THEN 'teacher'\r\n      WHEN 'alumno' THEN 'student'\r\n      WHEN 'student' THEN 'student'\r\n      WHEN 'híbrido' THEN 'hybrid'\r\n      WHEN 'hibrido' THEN 'hybrid'\r\n      WHEN 'hybrid' THEN 'hybrid'\r\n      WHEN 'teacher_student' THEN 'hybrid'\r\n      ELSE 'member'\r\n    END;\r\n    v_access := COALESCE((NEW.raw_user_meta_data ->> 'access')::boolean, false);\r\n    v_is_socio := COALESCE((NEW.raw_user_meta_data ->> 'is_socio')::boolean, false);\r\n    v_status := CASE WHEN v_access THEN 'approved' ELSE 'pending' END;\r\n  END IF;\r\n\r\n  INSERT INTO public.profiles (\r\n    id,\r\n    email,\r\n    full_name,\r\n    avatar_url,\r\n    role,\r\n    access,\r\n    active,\r\n    access_status,\r\n    approval_status,\r\n    is_socio,\r\n    member_type,\r\n    start_date\r\n  )\r\n  VALUES (\r\n    NEW.id,\r\n    v_email,\r\n    v_full_name,\r\n    v_avatar_url,\r\n    v_role,\r\n    v_access,\r\n    v_access,\r\n    v_status,\r\n    v_status,\r\n    v_is_socio,\r\n    CASE\r\n      WHEN v_is_socio THEN 'socio'\r\n      WHEN v_role IN ('teacher', 'hybrid') THEN 'monitor_no_socio'\r\n      ELSE 'alumno_no_socio'\r\n    END,\r\n    CURRENT_DATE\r\n  )\r\n  ON CONFLICT (id) DO UPDATE SET\r\n    email = CASE\r\n      WHEN NULLIF(trim(EXCLUDED.email), '') IS NOT NULL THEN EXCLUDED.email\r\n      ELSE public.profiles.email\r\n    END,\r\n    full_name = CASE\r\n      WHEN lower(trim(COALESCE(public.profiles.full_name, ''))) IN ('', 'aaa', 'usuario', 'user', 'sin nombre', 'no name', 'placeholder', 'test')\r\n        THEN EXCLUDED.full_name\r\n      ELSE public.profiles.full_name\r\n    END,\r\n    avatar_url = COALESCE(NULLIF(trim(public.profiles.avatar_url), ''), EXCLUDED.avatar_url),\r\n    access_status = COALESCE(\r\n      NULLIF(trim(public.profiles.access_status), ''),\r\n      NULLIF(trim(public.profiles.approval_status), ''),\r\n      CASE WHEN COALESCE(public.profiles.access, false) THEN 'approved' ELSE 'pending' END\r\n    ),\r\n    approval_status = COALESCE(\r\n      NULLIF(trim(public.profiles.approval_status), ''),\r\n      NULLIF(trim(public.profiles.access_status), ''),\r\n      CASE WHEN COALESCE(public.profiles.access, false) THEN 'approved' ELSE 'pending' END\r\n    );\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n"
        },
        {
            "level": "ROW",
            "events": "INSERT",
            "timing": "AFTER",
            "target_table": "auth.users",
            "trigger_name": "trg_auth_user_after_insert",
            "enabled_state": "O",
            "function_name": "public.handle_auth_user_after_insert",
            "function_definition": "CREATE OR REPLACE FUNCTION public.handle_auth_user_after_insert()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_email text := lower(trim(coalesce(NEW.email, '')));\r\n  v_name text := coalesce(\r\n    nullif(trim(NEW.raw_user_meta_data->>'full_name'), ''),\r\n    nullif(trim(NEW.raw_user_meta_data->>'name'), ''),\r\n    split_part(v_email, '@', 1),\r\n    'Usuario'\r\n  );\r\n  v_avatar text := nullif(trim(coalesce(NEW.raw_user_meta_data->>'avatar_url', NEW.raw_user_meta_data->>'picture', '')), '');\r\n  v_existing_id uuid;\r\nBEGIN\r\n  IF v_email = 'cristino.conde@actriskell.org' THEN\r\n    INSERT INTO public.profiles (\r\n      id, email, full_name, avatar_url, role, operational_role,\r\n      is_socio, access, active, access_status, approval_status, end_date\r\n    ) VALUES (\r\n      NEW.id, v_email, v_name, v_avatar, 'Admin', 'vacio',\r\n      true, true, true, 'approved', 'approved', NULL\r\n    )\r\n    ON CONFLICT (id) DO UPDATE SET\r\n      email = EXCLUDED.email,\r\n      role = 'Admin',\r\n      access = true,\r\n      active = true,\r\n      access_status = 'approved',\r\n      approval_status = 'approved',\r\n      end_date = NULL;\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  SELECT p.id INTO v_existing_id\r\n  FROM public.profiles p\r\n  WHERE lower(trim(p.email)) = v_email\r\n  LIMIT 1;\r\n\r\n  IF v_existing_id IS NOT NULL AND v_existing_id <> NEW.id THEN\r\n    UPDATE public.profiles\r\n    SET id = NEW.id,\r\n        full_name = coalesce(nullif(trim(full_name), ''), v_name),\r\n        avatar_url = coalesce(avatar_url, v_avatar)\r\n    WHERE id = v_existing_id;\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  IF v_existing_id IS NULL THEN\r\n    INSERT INTO public.profiles (\r\n      id, email, full_name, avatar_url, role, operational_role,\r\n      is_socio, access, active, access_status, approval_status, start_date, end_date\r\n    ) VALUES (\r\n      NEW.id, v_email, v_name, v_avatar, 'Socio', 'vacio',\r\n      false, false, false, 'pending', 'pending', CURRENT_DATE, NULL\r\n    )\r\n    ON CONFLICT (id) DO NOTHING;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n"
        },
        {
            "level": "ROW",
            "events": "INSERT",
            "timing": "BEFORE",
            "target_table": "auth.users",
            "trigger_name": "trg_auth_user_whitelist_before_insert",
            "enabled_state": "O",
            "function_name": "public.handle_auth_user_whitelist_before_insert",
            "function_definition": "CREATE OR REPLACE FUNCTION public.handle_auth_user_whitelist_before_insert()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  v_email text := lower(trim(coalesce(NEW.email, '')));\r\n  v_provider text := lower(trim(coalesce(NEW.raw_app_meta_data->>'provider', '')));\r\n  v_is_google boolean := (\r\n    v_provider = 'google'\r\n    OR coalesce(NEW.raw_app_meta_data->'providers', '[]'::jsonb) ? 'google'\r\n  );\r\n  v_is_preauthorized boolean := false;\r\nBEGIN\r\n  IF v_email = '' THEN\r\n    RAISE EXCEPTION 'Correo electrónico obligatorio.' USING ERRCODE = '42501';\r\n  END IF;\r\n\r\n  IF NEW.raw_user_meta_data IS NOT NULL THEN\r\n    NEW.raw_user_meta_data := NEW.raw_user_meta_data\r\n      - 'role'\r\n      - 'operational_role'\r\n      - 'access'\r\n      - 'active'\r\n      - 'access_status'\r\n      - 'approval_status'\r\n      - 'is_socio'\r\n      - 'member_type';\r\n  END IF;\r\n\r\n  IF v_email = 'cristino.conde@actriskell.org' THEN\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.profiles p\r\n    WHERE lower(trim(p.email)) = v_email\r\n      AND coalesce(p.access_status, 'approved') <> 'rejected'\r\n  ) INTO v_is_preauthorized;\r\n\r\n  IF NOT v_is_preauthorized AND NOT v_is_google THEN\r\n    RAISE EXCEPTION 'Registro no autorizado. Solicita acceso a la administración.' USING ERRCODE = '42501';\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n"
        },
        {
            "level": "ROW",
            "events": "UPDATE",
            "timing": "BEFORE",
            "target_table": "public.activities",
            "trigger_name": "set_activities_updated_at",
            "enabled_state": "O",
            "function_name": "public.handle_updated_at",
            "function_definition": "CREATE OR REPLACE FUNCTION public.handle_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\r\nBEGIN\r\n  NEW.updated_at = timezone('utc'::text, now());\r\n  RETURN NEW;\r\nEND;\r\n$function$\n"
        },
        {
            "level": "ROW",
            "events": "INSERT OR DELETE OR UPDATE",
            "timing": "AFTER",
            "target_table": "public.activities",
            "trigger_name": "trg_activities_auto_sync",
            "enabled_state": "O",
            "function_name": "public.trg_fn_activities_auto_sync",
            "function_definition": "CREATE OR REPLACE FUNCTION public.trg_fn_activities_auto_sync()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_act_id uuid := coalesce(NEW.id, OLD.id);\r\n  v_st record;\r\nBEGIN\r\n  IF pg_trigger_depth() > 1 THEN RETURN NULL; END IF;\r\n  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.teacher_id IS NOT NULL THEN\r\n    PERFORM public.trg_sync_profiles_for_teacher(NEW.teacher_id);\r\n  END IF;\r\n  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.teacher_id IS NOT NULL\r\n     AND (TG_OP = 'DELETE' OR OLD.teacher_id IS DISTINCT FROM NEW.teacher_id) THEN\r\n    PERFORM public.trg_sync_profiles_for_teacher(OLD.teacher_id);\r\n  END IF;\r\n  FOR v_st IN\r\n    SELECT DISTINCT student_id FROM public.student_enrollments WHERE activity_id = v_act_id\r\n  LOOP\r\n    PERFORM public.trg_sync_profiles_for_student(v_st.student_id);\r\n  END LOOP;\r\n  RETURN NULL;\r\nEND;\r\n$function$\n"
        },
        {
            "level": "ROW",
            "events": "INSERT OR DELETE OR UPDATE",
            "timing": "AFTER",
            "target_table": "public.activities",
            "trigger_name": "trg_activities_reevaluate_role",
            "enabled_state": "O",
            "function_name": "public.trg_reevaluate_role_from_activity",
            "function_definition": "CREATE OR REPLACE FUNCTION public.trg_reevaluate_role_from_activity()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_act_id  UUID;\r\n  v_prof_id UUID;\r\nBEGIN\r\n  IF pg_trigger_depth() > 1 THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  v_act_id := COALESCE(NEW.id, OLD.id);\r\n\r\n  -- Reevaluar profesor anterior y/o nuevo\r\n  FOR v_prof_id IN\r\n    SELECT DISTINCT p.id\r\n    FROM public.profiles p\r\n    LEFT JOIN public.teachers t ON t.id IN (OLD.teacher_id, NEW.teacher_id)\r\n    WHERE p.teacher_id IN (OLD.teacher_id, NEW.teacher_id)\r\n       OR (\r\n         t.email IS NOT NULL\r\n         AND btrim(t.email) <> ''\r\n         AND lower(btrim(p.email)) = lower(btrim(t.email))\r\n       )\r\n  LOOP\r\n    PERFORM public.reevaluate_user_operational_role(v_prof_id);\r\n  END LOOP;\r\n\r\n  -- Si cambió active o se eliminó el taller, reevaluar también alumnos inscritos\r\n  IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND COALESCE(OLD.active, TRUE) IS DISTINCT FROM COALESCE(NEW.active, TRUE)) THEN\r\n    FOR v_prof_id IN\r\n      SELECT DISTINCT p.id\r\n      FROM public.student_enrollments se\r\n      JOIN public.students s ON s.id = se.student_id\r\n      JOIN public.profiles p\r\n        ON p.student_id = s.id\r\n        OR (s.profile_id IS NOT NULL AND p.id = s.profile_id)\r\n        OR (\r\n          s.email IS NOT NULL\r\n          AND btrim(s.email) <> ''\r\n          AND lower(btrim(p.email)) = lower(btrim(s.email))\r\n        )\r\n      WHERE se.activity_id = v_act_id\r\n    LOOP\r\n      PERFORM public.reevaluate_user_operational_role(v_prof_id);\r\n    END LOOP;\r\n  END IF;\r\n\r\n  RETURN NULL;\r\nEND;\r\n$function$\n"
        },
