        {
            "level": "ROW",
            "events": "UPDATE",
            "timing": "BEFORE",
            "target_table": "public.profiles",
            "trigger_name": "trg_00_protect_profile_privileged_fields",
            "enabled_state": "O",
            "function_name": "public.protect_profile_privileged_fields",
            "function_definition": "CREATE OR REPLACE FUNCTION public.protect_profile_privileged_fields()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_uid uuid := auth.uid();\r\nBEGIN\r\n  IF v_uid IS NULL\r\n     OR current_setting('app.allow_profile_role_sync', true) = 'on'\r\n     OR pg_trigger_depth() > 1\r\n     OR public.is_admin() THEN\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  IF NEW.role IS DISTINCT FROM OLD.role\r\n     OR NEW.active IS DISTINCT FROM OLD.active\r\n     OR NEW.access IS DISTINCT FROM OLD.access\r\n     OR NEW.operational_role IS DISTINCT FROM OLD.operational_role\r\n     OR NEW.is_socio IS DISTINCT FROM OLD.is_socio\r\n     OR NEW.member_type IS DISTINCT FROM OLD.member_type\r\n     OR NEW.member_number IS DISTINCT FROM OLD.member_number\r\n     OR NEW.student_id IS DISTINCT FROM OLD.student_id\r\n     OR NEW.teacher_id IS DISTINCT FROM OLD.teacher_id THEN\r\n    RAISE EXCEPTION 'Solo la administración puede modificar el estado de acceso, rol, número de socio o vínculos.'\r\n      USING ERRCODE = '42501';\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n"
        },
        {
            "level": "ROW",
            "events": "INSERT OR UPDATE",
            "timing": "BEFORE",
            "target_table": "public.profiles",
            "trigger_name": "trg_05_assign_socio_member_number",
            "enabled_state": "O",
            "function_name": "public.trg_fn_assign_socio_member_number",
            "function_definition": "CREATE OR REPLACE FUNCTION public.trg_fn_assign_socio_member_number()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_row        JSONB := to_jsonb(NEW);\r\n  v_is_socio   BOOLEAN := COALESCE((v_row->>'is_socio')::boolean, false);\r\n  v_role       TEXT := v_row->>'role';\r\n  v_mtype      TEXT := v_row->>'member_type';\r\nBEGIN\r\n  IF NEW.member_number IS NOT NULL AND btrim(NEW.member_number) <> '' THEN\r\n    NEW.member_number := public.format_socio_member_number(NEW.member_number);\r\n  ELSIF v_is_socio OR v_role = 'socio' OR v_mtype = 'socio' THEN\r\n    NEW.member_number := lpad(nextval('public.socio_member_number_seq')::text, 5, '0');\r\n  ELSE\r\n    NEW.member_number := NULL;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n"
        },
        {
            "level": "ROW",
            "events": "INSERT OR UPDATE",
            "timing": "BEFORE",
            "target_table": "public.profiles",
            "trigger_name": "trg_profiles_auto_sync",
            "enabled_state": "O",
            "function_name": "public.trg_fn_profiles_auto_sync",
            "function_definition": "CREATE OR REPLACE FUNCTION public.trg_fn_profiles_auto_sync()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_op_role public.operational_role_type;\r\nBEGIN\r\n  IF pg_trigger_depth() > 1 THEN\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  IF lower(trim(COALESCE(NEW.email, ''))) = 'cristino.conde@actriskell.org' THEN\r\n    NEW.role := 'admin';\r\n    NEW.active := true;\r\n    NEW.access := true;\r\n    NEW.approval_status := 'approved';\r\n    NEW.end_date := NULL;\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  -- Si la cuenta sigue pendiente o fue rechazada/bloqueada, no otorgar acceso ni rol automático\r\n  IF COALESCE(NEW.approval_status, 'pending') IN ('pending', 'rejected')\r\n     AND COALESCE(NEW.access, NEW.active, false) = false THEN\r\n    NEW.operational_role := COALESCE(NEW.operational_role, 'vacio'::public.operational_role_type);\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  IF TG_OP = 'INSERT' OR (\r\n    NEW.is_socio IS DISTINCT FROM OLD.is_socio\r\n    OR NEW.student_id IS DISTINCT FROM OLD.student_id\r\n    OR NEW.teacher_id IS DISTINCT FROM OLD.teacher_id\r\n  ) THEN\r\n    v_op_role := public.derive_user_operational_role(NEW.student_id, NEW.teacher_id, NEW.email, NEW.id);\r\n    NEW.operational_role := v_op_role;\r\n\r\n    IF NEW.role IS DISTINCT FROM 'admin' THEN\r\n      CASE v_op_role\r\n        WHEN 'hibrido' THEN\r\n          NEW.role := 'hybrid';\r\n          NEW.active := true;\r\n          NEW.access := true;\r\n          NEW.approval_status := 'approved';\r\n          NEW.end_date := NULL;\r\n        WHEN 'alumno' THEN\r\n          NEW.role := 'student';\r\n          NEW.active := true;\r\n          NEW.access := true;\r\n          NEW.approval_status := 'approved';\r\n          NEW.end_date := NULL;\r\n        WHEN 'profesor' THEN\r\n          NEW.role := 'teacher';\r\n          NEW.active := true;\r\n          NEW.access := true;\r\n          NEW.approval_status := 'approved';\r\n          NEW.end_date := NULL;\r\n        ELSE\r\n          IF COALESCE(NEW.access, NEW.active, false) = true THEN\r\n            NEW.role := COALESCE(NULLIF(NEW.role, ''), 'member');\r\n            NEW.approval_status := 'approved';\r\n          END IF;\r\n      END CASE;\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n"
        },
        {
            "level": "ROW",
            "events": "UPDATE",
            "timing": "BEFORE",
            "target_table": "public.profiles",
            "trigger_name": "trg_protect_profile_auth_columns",
            "enabled_state": "O",
            "function_name": "public.protect_profile_auth_columns",
            "function_definition": "CREATE OR REPLACE FUNCTION public.protect_profile_auth_columns()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nBEGIN\r\n  IF lower(trim(COALESCE(OLD.email, NEW.email, ''))) = 'cristino.conde@actriskell.org' THEN\r\n    NEW.role := 'admin';\r\n    NEW.access := true;\r\n    NEW.active := true;\r\n    NEW.approval_status := 'approved';\r\n    NEW.end_date := NULL;\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  IF NEW.access IS DISTINCT FROM OLD.access THEN\r\n    NEW.active := NEW.access;\r\n  ELSIF NEW.active IS DISTINCT FROM OLD.active THEN\r\n    NEW.access := NEW.active;\r\n  END IF;\r\n\r\n  IF COALESCE(NEW.access, false) = true THEN\r\n    NEW.approval_status := 'approved';\r\n    NEW.end_date := NULL;\r\n    IF NEW.role IS NULL OR btrim(NEW.role) = '' THEN\r\n      NEW.role := 'member';\r\n    END IF;\r\n  ELSIF NEW.approval_status IS NULL THEN\r\n    NEW.approval_status := CASE WHEN NEW.end_date IS NOT NULL THEN 'rejected' ELSE 'pending' END;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n"
        },
        {
            "level": "ROW",
            "events": "UPDATE",
            "timing": "BEFORE",
            "target_table": "public.profiles",
            "trigger_name": "trg_protect_profile_privileged_columns",
            "enabled_state": "O",
            "function_name": "public.protect_profile_privileged_columns",
            "function_definition": "CREATE OR REPLACE FUNCTION public.protect_profile_privileged_columns()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth', 'pg_temp'\nAS $function$\r\nBEGIN\r\n  IF current_setting('app.bypass_profile_guard', true) = 'on'\r\n     OR auth.role() = 'service_role'\r\n     OR public.is_admin() THEN\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  NEW.role             := OLD.role;\r\n  NEW.operational_role := OLD.operational_role;\r\n  NEW.access           := OLD.access;\r\n  NEW.active           := OLD.active;\r\n  NEW.access_status    := OLD.access_status;\r\n  NEW.approval_status  := OLD.approval_status;\r\n  NEW.is_socio         := OLD.is_socio;\r\n  NEW.member_type      := OLD.member_type;\r\n  NEW.member_number    := OLD.member_number;\r\n  NEW.teacher_id       := OLD.teacher_id;\r\n  NEW.student_id       := OLD.student_id;\r\n  NEW.start_date       := OLD.start_date;\r\n  NEW.end_date         := OLD.end_date;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n"
        },
        {
            "level": "ROW",
            "events": "INSERT OR UPDATE",
            "timing": "AFTER",
            "target_table": "public.profiles",
            "trigger_name": "trg_sync_profile_member_number",
            "enabled_state": "O",
            "function_name": "public.trg_fn_sync_profile_member_number",
            "function_definition": "CREATE OR REPLACE FUNCTION public.trg_fn_sync_profile_member_number()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nBEGIN\r\n  IF pg_trigger_depth() > 1 THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  IF TG_OP = 'INSERT' OR NEW.member_number IS DISTINCT FROM OLD.member_number THEN\r\n    IF NEW.student_id IS NOT NULL THEN\r\n      UPDATE public.students\r\n      SET member_number = NEW.member_number\r\n      WHERE id = NEW.student_id\r\n        AND member_number IS DISTINCT FROM NEW.member_number;\r\n    END IF;\r\n\r\n    IF NEW.teacher_id IS NOT NULL THEN\r\n      UPDATE public.teachers\r\n      SET member_number = NEW.member_number\r\n      WHERE id = NEW.teacher_id\r\n        AND member_number IS DISTINCT FROM NEW.member_number;\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN NULL;\r\nEND;\r\n$function$\n"
        },
        {
            "level": "ROW",
            "events": "UPDATE",
            "timing": "BEFORE",
            "target_table": "public.session_attendances",
            "trigger_name": "set_session_attendances_updated_at",
            "enabled_state": "O",
            "function_name": "public.handle_updated_at",
            "function_definition": "CREATE OR REPLACE FUNCTION public.handle_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\r\nBEGIN\r\n  NEW.updated_at = timezone('utc'::text, now());\r\n  RETURN NEW;\r\nEND;\r\n$function$\n"
        },
        {
            "level": "ROW",
            "events": "UPDATE",
            "timing": "BEFORE",
            "target_table": "public.student_absences",
            "trigger_name": "trg_prevent_cancel_closed_class_absence",
            "enabled_state": "O",
            "function_name": "public.prevent_cancel_closed_class_absence",
            "function_definition": "CREATE OR REPLACE FUNCTION public.prevent_cancel_closed_class_absence()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_is_closed boolean := false;\r\n  v_is_staff boolean := false;\r\nBEGIN\r\n  IF OLD.status IS DISTINCT FROM 'cancelled' AND NEW.status = 'cancelled' THEN\r\n    SELECT EXISTS (\r\n      SELECT 1\r\n      FROM public.profiles p\r\n      WHERE p.id = auth.uid()\r\n        AND COALESCE(p.access, p.active, false) = true\r\n        AND p.role IN ('admin', 'teacher', 'hybrid')\r\n    ) INTO v_is_staff;\r\n\r\n    SELECT coalesce(bool_or(cs.is_closed), false)\r\n      INTO v_is_closed\r\n      FROM public.class_sessions cs\r\n     WHERE cs.activity_id = OLD.activity_id\r\n       AND cs.date = OLD.session_date;\r\n\r\n    IF v_is_closed AND NOT v_is_staff THEN\r\n      RAISE EXCEPTION 'No se puede anular el aviso de ausencia porque la clase ya ha sido cerrada por el monitor.';\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n"
        },
        {
            "level": "ROW",
            "events": "INSERT OR UPDATE",
            "timing": "AFTER",
            "target_table": "public.student_absences",
            "trigger_name": "trg_sync_student_absence_to_attendance",
            "enabled_state": "O",
            "function_name": "public.sync_student_absence_to_attendance",
            "function_definition": "CREATE OR REPLACE FUNCTION public.sync_student_absence_to_attendance()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_session RECORD;\r\n  v_att_id public.session_attendances.id%TYPE;\r\n  v_target_date text := left(NEW.session_date::text, 10);\r\n  v_present_count integer;\r\nBEGIN\r\n  IF NEW.status NOT IN ('reported', 'approved', 'cancelled') THEN\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  FOR v_session IN\r\n    SELECT id, COALESCE(is_closed, false) AS is_closed\r\n    FROM public.class_sessions\r\n    WHERE activity_id = NEW.activity_id\r\n      AND left(date::text, 10) = v_target_date\r\n  LOOP\r\n    IF NEW.status IN ('reported', 'cancelled') AND v_session.is_closed THEN\r\n      CONTINUE;\r\n    END IF;\r\n\r\n    SELECT id INTO v_att_id\r\n    FROM public.session_attendances\r\n    WHERE session_id = v_session.id\r\n      AND student_id = NEW.student_id\r\n    LIMIT 1;\r\n\r\n    IF NEW.status IN ('reported', 'approved') THEN\r\n      IF v_att_id IS NOT NULL THEN\r\n        UPDATE public.session_attendances\r\n        SET attendance = 'absent'\r\n        WHERE id = v_att_id;\r\n      ELSE\r\n        INSERT INTO public.session_attendances (\r\n          session_id, student_id, attendance, paid, paid_amount, payment_method, payment_id\r\n        ) VALUES (\r\n          v_session.id, NEW.student_id, 'absent', false, 0, 'cash', NULL\r\n        );\r\n      END IF;\r\n    ELSIF NEW.status = 'cancelled' THEN\r\n      IF v_att_id IS NOT NULL THEN\r\n        UPDATE public.session_attendances\r\n        SET attendance = 'present'\r\n        WHERE id = v_att_id\r\n          AND attendance = 'absent';\r\n      END IF;\r\n    END IF;\r\n\r\n    SELECT COUNT(*)::integer INTO v_present_count\r\n    FROM public.session_attendances\r\n    WHERE session_id = v_session.id\r\n      AND attendance <> 'absent';\r\n\r\n    UPDATE public.class_sessions\r\n    SET attendees_count = v_present_count\r\n    WHERE id = v_session.id;\r\n  END LOOP;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n"
        },
        {
            "level": "ROW",
            "events": "UPDATE",
            "timing": "BEFORE",
            "target_table": "public.student_enrollments",
            "trigger_name": "set_student_enrollments_updated_at",
