            "trigger_name": "trg_student_enrollments_auto_sync",
            "enabled_state": "O",
            "function_name": "public.trg_fn_enrollments_auto_sync",
            "function_definition": "CREATE OR REPLACE FUNCTION public.trg_fn_enrollments_auto_sync()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nBEGIN\r\n  IF pg_trigger_depth() > 1 THEN RETURN NULL; END IF;\r\n  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.student_id IS NOT NULL THEN\r\n    PERFORM public.trg_sync_profiles_for_student(NEW.student_id);\r\n  END IF;\r\n  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.student_id IS NOT NULL\r\n     AND (TG_OP = 'DELETE' OR OLD.student_id IS DISTINCT FROM NEW.student_id) THEN\r\n    PERFORM public.trg_sync_profiles_for_student(OLD.student_id);\r\n  END IF;\r\n  RETURN NULL;\r\nEND;\r\n$function$\n"
        },
        {
            "level": "ROW",
            "events": "INSERT OR DELETE OR UPDATE",
            "timing": "AFTER",
            "target_table": "public.student_enrollments",
            "trigger_name": "trg_student_enrollments_reevaluate_role",
            "enabled_state": "O",
            "function_name": "public.trg_reevaluate_role_from_enrollment",
            "function_definition": "CREATE OR REPLACE FUNCTION public.trg_reevaluate_role_from_enrollment()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_student_id UUID;\r\n  v_prof_id    UUID;\r\nBEGIN\r\n  IF pg_trigger_depth() > 1 THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  v_student_id := COALESCE(NEW.student_id, OLD.student_id);\r\n  IF v_student_id IS NULL THEN\r\n    RETURN NULL;\r\n  END IF;\r\n\r\n  FOR v_prof_id IN\r\n    SELECT DISTINCT p.id\r\n    FROM public.profiles p\r\n    LEFT JOIN public.students s ON s.id = v_student_id\r\n    WHERE p.student_id = v_student_id\r\n       OR (s.profile_id IS NOT NULL AND p.id = s.profile_id)\r\n       OR (\r\n         s.email IS NOT NULL\r\n         AND btrim(s.email) <> ''\r\n         AND lower(btrim(p.email)) = lower(btrim(s.email))\r\n       )\r\n  LOOP\r\n    PERFORM public.reevaluate_user_operational_role(v_prof_id);\r\n  END LOOP;\r\n\r\n  RETURN NULL;\r\nEND;\r\n$function$\n"
        },
