            "function_name": "public.trg_fn_assign_socio_member_number",
            "function_definition": "CREATE OR REPLACE FUNCTION public.trg_fn_assign_socio_member_number()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_row        JSONB := to_jsonb(NEW);\r\n  v_is_socio   BOOLEAN := COALESCE((v_row->>'is_socio')::boolean, false);\r\n  v_role       TEXT := v_row->>'role';\r\n  v_mtype      TEXT := v_row->>'member_type';\r\nBEGIN\r\n  IF NEW.member_number IS NOT NULL AND btrim(NEW.member_number) <> '' THEN\r\n    NEW.member_number := public.format_socio_member_number(NEW.member_number);\r\n  ELSIF v_is_socio OR v_role = 'socio' OR v_mtype = 'socio' THEN\r\n    NEW.member_number := lpad(nextval('public.socio_member_number_seq')::text, 5, '0');\r\n  ELSE\r\n    NEW.member_number := NULL;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n"
        },
