            "trigger_name": "trg_sync_profile_on_student_link",
            "enabled_state": "O",
            "function_name": "public.sync_profile_on_student_link",
            "function_definition": "CREATE OR REPLACE FUNCTION public.sync_profile_on_student_link()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nBEGIN\r\n  IF NEW.profile_id IS NOT NULL THEN\r\n    PERFORM set_config('app.allow_profile_role_sync', 'on', true);\r\n    UPDATE public.profiles\r\n    SET\r\n      student_id = NEW.id,\r\n      role = CASE\r\n        WHEN role = 'teacher' THEN 'hybrid'\r\n        ELSE role\r\n      END,\r\n      updated_at = NOW()\r\n    WHERE id = NEW.profile_id;\r\n    PERFORM set_config('app.allow_profile_role_sync', 'off', true);\r\n  END IF;\r\n  RETURN NEW;\r\nEND;\r\n$function$\n"
        },
